-- wger exercises, part 2 (generated by scripts/import_wger.py; CC licences, author per row).
-- Existing exercises win: a clashing name or id is skipped.
insert into public.exercises (id, name, main_muscles, form_instructions, equipment, source, license, author, source_url)
values
  ('456f0781-30c6-4f58-a5b4-3da8f4878065', 'Dumbbell Calf Raise', 'Calves', 'Stand upright with a dumbbell in each hand, arms hanging at your sides and feet hip-width apart. For a larger range of motion, stand with the balls of your feet on a step or a weight plate.
Rise up onto your toes as high as you can and pause briefly at the top. Then lower your heels slowly until you feel a stretch in your calves. Keep your knees straight but not locked and your upper body upright.', 'Dumbbell', 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/2661/view/'),
  ('31a58615-d3ae-4233-9c50-9143c899ce8c', 'Dumbbell Cheat Curl', 'Biceps', '- Starting position is standing
with feet shoulder width apart.
- Hands should take an underhand
or supinated grip on the dumbbells holding them with hands shoulder
width apart.
- Keeping elbows tucked into your
sides throughout the entire movement, use momentum to curl the dumbbells,
squeezing your biceps at the top of the movement.
- Slowly lower to return to the
starting position. Keep the core tight throughout the exercise.
Cheating
through the concentric curling portion of this challenging exercise gives us a
great opportunity to increase time under tension and create eccentric overload
with heavier weight when we lower.', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'Moffi', 'https://wger.de/en/exercise/1482/view/'),
  ('428112f3-3918-45ba-870a-dc58cf3959cf', 'Dumbbell close grip bench press', 'Chest, Triceps', 'Lie down with your back on a flat bench. Hold a dumbbell in each hand. Raise your arms towards the ceiling with your palms facing each other and dumbbells pressed together.
Slowly lower the dumbbells to your chest, then slowly push them back. Repeat the exercise.', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'Lynn_McIntyre', 'https://wger.de/en/exercise/1228/view/'),
  ('46e0f60c-fdc0-489a-82e4-a5b7476a5c21', 'Dumbbell Concentration Curl', 'Brachialis', 'Sit on bench. Grasp dumbbell between feet. Place back of upper arm to inner thigh. Lean into leg to raise elbow slightly.', 'Dumbbell', 'wger', 'CC-BY-SA 3', 'http://www.exrx.net/WeightExercises/Brachialis/DBC', 'https://wger.de/en/exercise/202/view/'),
  ('b48e4d9d-f7fc-4619-85fb-6dabe5d7c999', 'Dumbbell Crunches', 'Abs', 'Dumbbell crunches are a weighted variation of traditional crunches designed to target the abdominal muscles more intensely. Lie flat on your back with your knees bent and feet flat on the floor. Hold a dumbbell with both hands close to your chest or above your head. Lift your shoulders and upper back off the ground in a crunching motion, engaging your core. Slowly lower yourself back to the starting position. Ensure controlled movements throughout the exercise to prevent strain.', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'hpmbala@gmail.com', 'https://wger.de/en/exercise/1415/view/'),
  ('99846da5-5dc8-4de1-ba55-ae2b4c03c30d', 'Dumbbell Curl', 'Biceps, Brachialis', 'The Dumbbell Curl is a classic isolation exercise for the arms. Unlike the Hammer Curl, it involves rotating your wrists (supination) as you lift the weights, which allows for a full contraction of the biceps.', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'amaesc', 'https://wger.de/en/exercise/1931/view/'),
  ('e547df0d-d9aa-4c39-af40-59667aaa2cc9', 'Dumbbell cyclist squat', 'Hamstrings, Calves, Quads', 'Dumbbell squats with elevated heel position. Stand on either squat wedges or weight plates to raise heels higher than toes, while holding the dumbbells on your sides.', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'JuustoKakku', 'https://wger.de/en/exercise/2682/view/'),
  ('b199baca-7353-4dee-bbcf-620f96dba5b4', 'Dumbbell Deadlift', 'Hamstrings, Glutes', '- Controlled execution
- Don''t use momentum
- Slow execution', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'Anastasious', 'https://wger.de/en/exercise/1370/view/'),
  ('2539f907-0c10-4af5-807c-48cd15fd0878', 'Dumbbell donkey kick', 'Hamstrings, Glutes', 'The dumbbell donkey kick is an effective exercise for working the glute and hamstring muscles. This exercise is usually performed on all fours, using a dumbbell to add resistance. The steps for performing it correctly are described below.
Starting position: Get on all fours on a mat, with your hands aligned under your shoulders and your knees aligned under your hips.
Placing the dumbbell: Take a dumbbell and place it behind the knee of the leg you are going to lift. Make sure it is held securely to prevent it from falling during the exercise.
Exercise:
Inhale and, as you exhale, lift the leg with the dumbbell upward, keeping the knee bent at a 90-degree angle.
Raise the leg until it is parallel to the floor, feeling the contraction in the glutes.
Hold the position for one second at the top and then slowly lower the leg back to the starting position.
Repetitions: Perform 10 to 15 repetitions per leg, making sure to maintain good form throughout the exercise.
Sets: Complete 2 to 3 sets, depending on your fitness level.', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'Tierrasverdes', 'https://wger.de/en/exercise/1616/view/'),
  ('2418b290-801c-45fd-a990-fc9f234ab1e5', 'Dumbbell drag curls', 'Biceps', 'Hold a dumbbell in each hand with your palms facing forward. Pull your elbows back and lift the dumbbells to your chest height. Slowly lower the dumbbell and repeat the exercise.', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'Lynn_McIntyre', 'https://wger.de/en/exercise/1224/view/'),
  ('3393db0b-98b7-4d53-a0d4-985f97875295', 'Dumbbell farmer''s carry', null, 'Grab half your body weight in each hand and walk.', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'philip', 'https://wger.de/en/exercise/1116/view/'),
  ('e4966cb8-9089-4595-9c78-99a27821e6ff', 'Dumbbell Floor Press', 'Chest', 'Grab your dumbbells and lay flat on your back with your knees bent and your feet flat on the ground (use a bench if you have one). Press the weights up, locking out your elbows (A). Lower them slowly until your upper arms are resting on the floor (B) close to your body. Pause here before explosively pressing back up. Squeeze your chest hard and repeat.', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'admin', 'https://wger.de/en/exercise/1084/view/'),
  ('b407768d-d519-47b8-818a-44c9761a8be6', 'Dumbbell Frog Press', 'Glutes', 'Similar to hip thrust, but with feet put up together, lifting the butt off the ground in a frog like position.', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'JohnPreston', 'https://wger.de/en/exercise/1503/view/'),
  ('4621b41f-0d32-4033-acff-dc079c792606', 'Dumbbell Front Squat', 'Glutes, Quads', 'This exercise involves holding a dumbbell in each hand at shoulder height and performing a squat. It targets the lower body muscles, including the quads, hamstrings, and glutes, while also engaging the core and upper body.', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'AlucardEvil40', 'https://wger.de/en/exercise/1640/view/'),
  ('b7c6a444-90ea-4f5b-9fea-748311606eaa', 'Dumbbell Goblet Squat', 'Quads', 'Grasp dumbbell with both hands at the sides of the upper plates. Hold dumbbell in front of chest, close to torso. Place feet about shoulderwide apart, keep knees slightly bent.
Squat down until thighs are parallel to floor. Keep back straight, bend and move hips backward to keep knees above feet. Return, keep knees slightly flexed. Repeat.
Keep bodyweight on heels and look ahead or slightly above to keep back straight.', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'ataraxie67', 'https://wger.de/en/exercise/203/view/'),
  ('f0f53b8e-0136-4195-baf3-781903651359', 'Dumbbell Hang Power Cleans', 'Hamstrings, Glutes', 'On your feet, stand tall with your dumbbells, holding them at your sides. Hinge at the hips to lower them to your knees (picture 1). Stand back up with a slight jump, using the momentum to pull the dumbbells up on to your shoulders (picture 2). Stand up straight, then lower under control to your sides and repeat. Keep this fast and explosive; if your heart rate doesn’t hit the roof, you’re doing them wrong.', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'philip', 'https://wger.de/en/exercise/1087/view/'),
  ('587af8f1-516b-44c3-8660-70f262e1bef8', 'Dumbbell Hex Press', 'Chest, Triceps', '- Engage the muscles
- Position your feet wide
- Controlled movement
- Slow movement
- Bring the weights toward your lower chest/stomach', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'Anastasious', 'https://wger.de/en/exercise/1353/view/'),
  ('af77220c-098c-47c2-9f8c-92a651998903', 'Dumbbell Hip Thrust', 'Glutes, Quads', 'This exercise involves sitting on the ground with a dumbbell resting on the hips, then thrusting the hips upward while squeezing the glutes. It is a great exercise for strengthening the glutes and improving hip mobility.', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'AlucardEvil40', 'https://wger.de/en/exercise/1642/view/'),
  ('43e85cb8-51d0-4892-b1bf-80a3cb111ff6', 'Dumbbell Incline Curl', 'Biceps', '- Setup: Set an adjustable bench to an incline of approximately 45 to 60 degrees.
- Starting Position: Sit back against the bench with a dumbbell in each hand. Let your arms hang straight down toward the floor with your palms facing forward (supinated grip).
- The Curl: Keeping your upper arms stationary and shoulders pinned back against the bench, exhale and curl the weights upward toward your shoulders.
- Peak Contraction: Squeeze your biceps hard at the top of the movement, ensuring your elbows do not swing forward.
- The Descent: Inhale and slowly lower the dumbbells back to the starting position, maintaining full control and feeling the stretch in the biceps.', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'ExRx', 'https://wger.de/en/exercise/204/view/'),
  ('0213d6b0-993f-4b3d-97bf-3352afc18534', 'Dumbbell Lateral Raise (Custom)', 'Shoulders', 'Perform Dumbbell Lateral Raise with controlled form, keeping tension on the target muscles, pausing briefly at the peak contraction, then returning slowly under control without using momentum.', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'ruochenma', 'https://wger.de/en/exercise/2724/view/'),
  ('2f1a2707-e7ff-46ac-9112-3e31e6e961ee', 'Dumbbell Lunges Standing', 'Quads', '.', 'Dumbbell', 'wger', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/205/view/'),
  ('dcc6e237-a8bb-4eca-bbc5-7fb852636f6a', 'Dumbbell Lunges Walking', 'Quads', '- Starting Position: Stand with feet hip-width apart and hands either on your hips or holding dumbbells at your sides.
- The Stride: Take a wide step forward with your right leg.
- The Descent: Lower your hips until both knees are bent at approximately 90-degree angles.
- The Transition: Drive through your front heel to stand up, bringing your back foot forward to step directly into the next lunge.', 'Dumbbell', 'wger', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/206/view/'),
  ('68e5eae7-7fd0-4d69-9b50-d0df15feac91', 'Dumbbell Push-Up', 'Chest', 'Normal Push-ups on Dumbbells, this brings a further range of movement', 'Dumbbell', 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/801/view/'),
  ('adb6067f-fd48-4a25-a9b4-0793c5f158fa', 'Dumbbell rear delt row', 'Shoulders, Brachialis, Trapezius', 'Hold a dumbbell in each hand. Bend at your hips to make your back almost parallel to the floor. Let your arms hang down. Keep your arms in line with your shoulders. bend and lift your elbows out to the sides until your upper arms are parallel to the floor. Slowly return and repeat', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'Lynn_McIntyre', 'https://wger.de/en/exercise/1227/view/'),
  ('75e34967-b0ec-40d5-811e-b474b234a7a9', 'Dumbbell Rear Lunge', 'Glutes, Quads', 'This exercise involves holding a dumbbell in each hand and stepping back into a lunge position, then returning to standing. It primarily targets the glutes, hamstrings, and quadriceps.', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'AlucardEvil40', 'https://wger.de/en/exercise/1651/view/'),
  ('65d12ecf-54b8-466d-a412-e55c396cad69', 'Dumbbell Romanian Deadlift', 'Hamstrings, Glutes', 'This exercise involves holding a dumbbell in each hand and bending forward at the hips while keeping the back straight, then returning to a standing position. It primarily targets the hamstrings and glutes.', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'AlucardEvil40', 'https://wger.de/en/exercise/1652/view/'),
  ('d420baf8-977b-499e-8f91-416374227b91', 'Dumbbell Scaption', 'Trapezius', 'Starting position:
Stand upright with your feet shoulder-width apart.
Hold a dumbbell in each hand with a neutral grip (palms facing each other).
Keep a slight bend in your elbows, shoulders relaxed and shoulder blades pulled back.
Execution:
Slowly raise the dumbbells forward and slightly to the side, at about a 30–45° angle from your body (between a front raise and a lateral raise).
Lift until your arms are about shoulder height (do not go overhead).
Pause for a second at the top and feel the activation in your shoulders and scapular stabilizers.
Lower the dumbbells back down under control to the starting position.
Breathing:
Inhale as you lower the dumbbells.
Exhale as you lift them.
Common mistakes:
Using dumbbells that are too heavy (causing jerky movements).
Lifting above shoulder height (puts unnecessary stress on the shoulder joint).
Arching the lower back instead of keeping the movement controlled at the shoulders.
Purpose of the exercise:
Activates the lower trapezius, serratus anterior, and scapular stabilizers.
Helps correct posture and improve shoulder balance.', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'zdelko', 'https://wger.de/en/exercise/1602/view/'),
  ('5a9f4fa4-6b71-4bc7-a284-e76e43e3106a', 'Dumbbell Shoulder Rotations', 'Shoulders', 'Dumbbell shoulder rotations are designed to strengthen the rotator cuff muscles and improve shoulder stability and mobility.
- External Rotation: Hold a dumbbell in one hand, keeping your elbow bent at 90 degrees and close to your body. Rotate your forearm outward, away from your body, keeping your elbow stationary. Slowly return to the starting position.
- Internal Rotation: Hold a dumbbell in one hand, keeping your elbow bent at 90 degrees and close to your body. Rotate your forearm inward, toward your body, and slowly return to the starting position. Perform the exercise with controlled movements to avoid strain.', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'hpmbala@gmail.com', 'https://wger.de/en/exercise/1429/view/'),
  ('3e9b3bb0-7958-4836-89a5-ed0c5f7eeb03', 'Dumbbell Side Bend', 'Obliquus externus abdominis', 'This exercise involves holding a dumbbell in one hand and bending sideways to work the oblique muscles on the side of the body. It can be done standing or seated and is often used as a core strengthening exercise.', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'AlucardEvil40', 'https://wger.de/en/exercise/1650/view/'),
  ('412ba9ab-ae29-4411-9bbc-74af1263494c', 'Dumbbell Side Squat', 'Glutes, Quads', 'This exercise involves holding a dumbbell in one hand and performing a squat while stepping to the side. It targets the legs, glutes, and core muscles.', null, 'wger', 'CC-BY-SA 4', 'AlucardEvil40', 'https://wger.de/en/exercise/1653/view/'),
  ('7cc24acf-3fc9-4d14-a461-cd00d1d18f0e', 'Dumbbell Single-leg Hip Thrust', 'Glutes', 'The single-leg hip thrust is performed by placing your upper back on a weight bench, raising one leg, and extending the hip of the other leg to achieve an isolated contraction of the glute.
By working each side separately, you can fully isolate your glutes unilaterally, providing maximal training stimulus.', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'carlos3c', 'https://wger.de/en/exercise/1234/view/'),
  ('51fe0871-1390-4755-bd04-01a93e32f533', 'dumbbell snatch', 'Hamstrings, Glutes, Quads', 'Key Steps to Execute Correctly:
Setup: Place the dumbbell between your feet, with your shoulders above your hips, chest up, and back flat.
The Pull: Explosively extend your hips, knees, and ankles (triple extension) to drive the dumbbell upward, keeping your elbow high and the dumbbell close to your body.
The Catch: Quickly flex your hips and knees to drop under the dumbbell and receive it overhead with your arm locked in position, landing in a half-squat stance.
Common Mistakes: Using your arms too much to lift the weight instead of your legs, having a low elbow during the pull phase, and misaligning your shoulder, elbow, and wrist in the final position. For beginners, it’s recommended to start with light loads, focus on technique, and perform 3 to 5 sets of 3 to 5 reps per arm.', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'Aleid', 'https://wger.de/en/exercise/1947/view/'),
  ('8a3e08ab-4e97-4aee-897a-60d8693b9b43', 'Dumbbell Split Squat', 'Glutes, Quads', '- Controlled execution
- No momentum
- Execute slowly', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'Anastasious', 'https://wger.de/en/exercise/1366/view/'),
  ('0c30c543-e2cc-499b-bc31-8c28db445ed2', 'Dumbbell sumo deadlift', 'Hamstrings, Glutes', 'Lower your dumbbell to the ground between your legs. Assume a wide stance and with a straight back squat down. With the dumbbell standing upright, grip it by the top of the ‘head’ (picture 1).Keeping your chest up and core braced, push the floor away, driving back upwards to a standing position (picture 2). Repeat. If you can easily achieve 20-30 reps, use two dumbbells.', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'philip', 'https://wger.de/en/exercise/1088/view/'),
  ('ae6a522e-db10-45ba-9642-987468d8a4de', 'Dumbbell Thruster', 'Hamstrings, Glutes, Quads', 'Start with the dumbbells resting on your shoulders and squat down. Push
into standing and raise the dumbbells into an overhead position. Bring
the dumbbells back to your shoulders and repeat.', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'meldun', 'https://wger.de/en/exercise/1684/view/'),
  ('d8bddb58-91b0-4d7b-8ec1-cd742584b607', 'Dumbbell Triceps Extension', 'Triceps', 'Position one dumbbell over head with both hands under inner plate (heart shaped grip).
With elbows over head, lower forearm behind upper arm by flexing elbows. Flex wrists at bottom to avoid hitting dumbbell on back of neck. Raise dumbbell over head by extending elbows while hyperextending wrists. Return and repeat.', 'Dumbbell', 'wger', 'CC-BY-SA 3', 'tuninx', 'https://wger.de/en/exercise/211/view/'),
  ('fe3fbc98-26b2-4476-a7b9-8d3d3cac75b6', 'Dumbbell Ulnar Deviation', null, 'Stand with your arm straight down by your side. Hold a dumbbell by one end of the handle with the weighted end pointing behind you. Keeping the arm still, lift the weighted end up behind you using only the wrist, then lower it slowly. This is the opposite of wrist rising and keeps the wrist balanced.', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'lightking', 'https://wger.de/en/exercise/2739/view/'),
  ('1dca10f9-a976-4a09-ab85-b95fafaa1a28', 'Dumbbell Underhand Dead Row', 'Biceps', 'The Dumbbell Underhand Dead Row will involve the back, which means you can try a bit heavier weight. The catch is that you need to be able to control the weight for all the reps.
- Start by holding a pair of dumbbells with your feet shoulder-wide apart and your knees slightly bent.
- Hinge at your hips to lower your torse forward until it''s almost parallel to the floor, keeping your back flat and maintaining a slight bend in your knees.
- Exhale as you row the dumbbells to your sides up to chest height, leading with your elbows until your upper arms are just past parallel to the floor and the dumbbells are at ribcage level.
- Slowly lower to the starting position and repeat. Keep your back flat all the time.', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'Moffi', 'https://wger.de/en/exercise/1463/view/'),
  ('fd38d854-a244-4646-842b-ef1e0fbfede8', 'Dumbbell wide bicep curls', 'Biceps', 'Hold a dumbbell in each hand with your hands slightly wider than shoulder-width apart and palms facing forward.
Bend your elbows and lift the dumbbells to your shoulders. Slowly return and repeat.', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'Lynn_McIntyre', 'https://wger.de/en/exercise/1225/view/'),
  ('0de2d18f-7cea-40a2-ac88-bb72805e234f', 'Dumbbell Wrist Rising', null, 'Stand tall with your arm hanging straight down by your side. Hold a dumbbell by one end of the handle so the weighted end points forward and your thumb is on top. Keep the arm completely still and tip the weighted end up toward the ceiling using only the wrist, then lower it slowly. This trains radial deviation, the riser used in arm wrestling. Slide your hand further from the weight to make it harder.', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'lightking', 'https://wger.de/en/exercise/2725/view/'),
  ('fe328b2b-cc6d-4f12-a2c6-85ce374217c7', 'Dumbbells on Scott Machine', 'Biceps', null, 'Dumbbell', 'wger', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/208/view/'),
  ('2affa71f-7308-4448-af57-dc44b424090e', 'Dumbell Tate Press', 'Triceps', '- Set Up: Lie flat with a dumbbell in each hand. Extend your arms straight up over your chest as if you were at the top of a dumbbell bench press
- Starting Position: Position the dumbbells so they are touching or very close together with a pronated grip (palms facing your feet and thumbs facing each other)
- Lowering: Without moving your upper arms or shoulders, bend your elbows and flare them outward to the sides. Lower the inner ends of the dumbbells toward the center of your chest
- Touch and Pause: Gently touch the dumbbells to your chest. Do not rest the weight on your body; maintain constant tension in your triceps
- Press: Forcefully extend your elbows to return the dumbbells to the starting position. Focus on "pushing your pinkies toward the sky" to maximize triceps engagement
https://www.youtube.com/watch?v=IgSjoXbpy1M&t=2', 'Bench, Dumbbell', 'wger', 'CC-BY-SA 4', 'beagle', 'https://wger.de/en/exercise/1824/view/'),
  ('73dbe7a5-e8f3-48fd-814e-bc3378c15be2', 'Dynamic Planche', 'Abs', '- Start in a plank position, with your hands directly under your shoulders and your feet hip-width apart.
- Engage your core to keep your body in a straight line from head to toe.
- From this position, bend your knees slightly and jump with both feet inward, bringing them as close to your core as possible
- As soon as your feet touch the ground, push off forcefully to jump again and return to the starting plank position.
- Continue repeating this jumping motion, maintaining control and core stability throughout the exercise.
- Make sure to keep your breathing steady while jumping, breathing deeply and controlling your breathing.
- Keep your gaze fixed on the ground to maintain proper spinal alignment.
- Repeat the jumps for the desired length of time or the number of repetitions recommended for your workout program.
- To finish the exercise, rest by releasing the plank position, then stretch if necessary to loosen your muscles.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'painDpice', 'https://wger.de/en/exercise/1286/view/'),
  ('45d89ca5-f5c7-4e56-9833-fd160cd2666d', 'Dynamic side hold', 'Obliquus externus abdominis', 'Sling a rubber band on a kettlebell and lift the kettlebell by the rubber band. Let it hang by your side and stand on one leg, switch leg while continuing hold. Repeat with other hand', 'Kettlebell', 'wger', 'CC-BY-SA 4', 'philip', 'https://wger.de/en/exercise/1099/view/'),
  ('81c6b9ef-7cb7-4328-8cb4-47ae8ecc42be', 'Dynamic side plank', 'Obliquus externus abdominis', 'The dynamic side plank involves positioning yourself on your side, supported on one elbow and the side of your foot, then dipping your hips up and down while keeping your body in a straight line.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'painDpice', 'https://wger.de/en/exercise/1288/view/'),
  ('ddf4111d-907d-4d6c-b583-58323b96ca03', 'Easy Continuous Swim (Freestyle)', 'Shoulders, Lats, Chest', 'Swim freestyle at a relaxed, steady pace without stopping — think conversation pace, not racing. Focus on smooth, even strokes rather than speed or breathing technique; this is just to get your body moving and your heart rate up.', null, 'wger', 'CC-BY-SA 4', 'Imported from swim plan', 'https://wger.de/en/exercise/2480/view/'),
  ('1d1a53dd-e00f-477e-83f7-09c8ef9a71cd', 'elbow lever', 'Abs', '​A calisthenics static balance skill where the entire body is held straight and parallel to the ground, supported by tucking the elbows firmly into the abdomen or pelvic bones.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'ege', 'https://wger.de/en/exercise/2531/view/'),
  ('732a9a7f-fb45-41ea-94a3-6a7246a699f6', 'Elbows Tucked DB Bench Press', 'Triceps', 'Elbows Tucked DB Bench Press, chest press movement focusing on the triceps. DB stays parallel with body', 'Bench, Dumbbell', 'wger', 'CC-BY-SA 4', 'JohnPreston', 'https://wger.de/en/exercise/1498/view/'),
  ('34cce09a-edb3-4140-892a-1cf70da8d98b', 'Elephant Walks', 'Hamstrings', 'Hinge at your hips until you feel a stretch behind your knees. Bend one leg while the other is straight then fluidly bend the other knee while straightening the first knee.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'captive0592', 'https://wger.de/en/exercise/1391/view/'),
  ('e205aa88-c7b8-43a7-a527-c881b2d5f259', 'Elevated Hamstring Stretch', 'Hamstrings', 'Stand facing a bar, box or bench at roughly hip height and place the heel of one leg on it. Keep that leg straight with the toes pointing up, and keep the standing leg straight with both hips square to the support.
Hinge forward at the hips with a flat back until you feel a stretch in the back of the elevated thigh. Hold the position while breathing calmly, then switch legs.
Stretch for the hamstrings. The height of the support controls the intensity: the higher the leg, the stronger the stretch.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/2615/view/'),
  ('302e02df-4270-4a0b-8c5d-b743cdb06fc9', 'Elevated prayer stretch', 'Lats', 'Starting position:
Kneel in front of a bench, far enough so that your torso can fit between your knees and the bench. With your back straight, place your elbows on the bench, with palms together, hands pointing up.
Steps:
- On exhale, stretch your chest down toward the floor without moving your lower back. At the same time, bring your hands toward your shoulders, keeping palms together and elbows on the bench.
- Hold for a few seconds.
- On inhale, relax your back to return to the starting position.
-
- Repeat.', 'Bench', 'wger', 'CC-BY-SA 4', 'tinman', 'https://wger.de/en/exercise/1027/view/'),
  ('95a300de-2ad8-492e-9364-13766d9e7618', 'Elliptical', 'Glutes, Quads, Trapezius', 'It improves muscle toning, strengthens the leg muscles (quads, glutes, calves), helps vascularisation and increases resistance. The elliptical is also very useful if you aim to lose weight. Teste', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/962/view/'),
  ('29a361d5-1300-4fb4-90d6-d6350bec9cb9', 'Exercise Band Dorsiflexion', 'Soleus', 'This exercise uses an exercise band. It targets the Soleus and Tibialis anterior.', 'Resistance band', 'wger', 'CC-BY-SA 4', 'erikocobra', 'https://wger.de/en/exercise/1241/view/'),
  ('70c97a79-5e88-4549-a74c-0e5190a5c048', 'Exercise Band Plantarflexion', 'Calves', 'Banded plantarflexion is a great way to bridge the gap between plantarflexion range of motion and the more strenuous calf raises in weight bearing. This can help strengthen the calf muscles, load the Achilles tendon, and improve plantarflexion range of motion.', 'Resistance band', 'wger', 'CC-BY-SA 4', 'erikocobra', 'https://wger.de/en/exercise/1242/view/'),
  ('c3468685-73e4-4c3f-8197-b3a2e32f1c14', 'Exhale and Body-position Swim Drill', 'Shoulders, Lats', 'Swim one short pool length at a gentle pace while focusing on a relaxed body position and a steady exhale into the water between breaths. Pause at the wall between lengths. This is a moving swim technique drill, not stationary bobbing or a kickboard-only exercise.', null, 'wger', 'CC-BY-SA 4', 'Original exercise instructions prepared for nalhilal', 'https://wger.de/en/exercise/2692/view/'),
  ('253813a0-b33f-48b3-991e-ca66116e053f', 'Explosive Push-Ups', 'Chest', 'Explosive Push-Ups
Start in a standard push-up position, lower your chest, then explosively push off the ground so your hands leave the floor. Land softly and immediately repeat.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'ege', 'https://wger.de/en/exercise/2529/view/'),
  ('a4413bcc-dcd1-4332-a09a-fee94a265e22', 'External Rotation Stretch', 'Shoulders, Trapezius', '- Sit with your feet pressed against each other, and one knee raised all the way out to the side of your body.
- Place your elbow on your raised knee, bend it at 90 degrees, and point your hand directly forward, holding your barbell/dumbbell.
- Keep your shoulder depressed and retracted, raise your hand until your forearm is vertical, as if you were about to wave at someone like a robot.
- Lower your hand to the original position and repeat.', 'Barbell', 'wger', 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/1835/view/'),
  ('ab808c2c-2e84-42bb-a65d-287a06ca7aa2', 'Extreme Lat Stretch', null, 'Deep loaded stretch for latissimus dorsi, performed after pulling movements.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/1921/view/'),
  ('3c33c9fd-20cc-4dff-ac88-c992bb9b2e33', 'Extreme Pec Stretch', null, 'Deep loaded stretch for pectorals, typically performed at end of chest work.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/1919/view/'),
  ('4925b6c0-bbe6-4864-a649-23ec18d49985', 'Extreme Shoulder Stretch', null, 'Deep loaded stretch for deltoids, performed after pressing movements.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/1920/view/'),
  ('7bf4e131-d4a3-44c0-8fca-9e10002492e7', 'Face pulls with yellow/green band', 'Lats', 'Face pulls with band – standing horizontal pull. Grab the band at face height, pull elbows high and wide towards your face while squeezing shoulder blades together. Trains upper back, rear shoulders and improves posture.', 'Resistance band', 'wger', 'CC-BY-SA 4', '54str', 'https://wger.de/en/exercise/1732/view/'),
  ('d7a418d4-d0cb-4f85-8a7c-1e9d97152cbd', 'Facepull', 'Trapezius', 'Attach a rope to a pulley station set at about chest level.
Step back so you''re supporting the weight with arms completely outstretched and assume a staggered (one foot forward) stance. Bend the knees slightly for a stable base.
Retract the scapulae (squeeze your partner''s finger with your shoulder blades) and pull the center of the rope slightly up towards the face. A good cue is to think about pulling the ends of the rope apart, not just pulling back.
As you near your face, externally rotate so your knuckles are facing the ceiling.
Hold for one second at the top position and slowly lower.', 'Cable machine', 'wger', 'CC-BY-SA 4', 'abeworld', 'https://wger.de/en/exercise/222/view/'),
  ('325539fb-1227-4163-ab92-dea7a35d8b79', 'Fat Grip Dumbbell Hold', null, 'Fit thick grip sleeves over two dumbbell handles, or wrap the handles in a towel to make them thicker. Stand tall holding one in each hand at your sides and hold for the set time without letting the handles roll in your hands. The thicker handle makes your fingers and thumb work much harder than a normal grip.', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'lightking', 'https://wger.de/en/exercise/2744/view/'),
  ('1f007908-7f4b-416e-b8a2-1d61a7cab259', 'Feet-assisted Straight-bar Support', 'Triceps', 'Hold a stable straight bar in front of the hips with both arms straight. Keep both feet on the floor or a stable platform so they assist your body weight. Maintain steady shoulders and a controlled supported position without swinging. This is a feet-assisted straight-bar support hold, not a ring hold or a full dip.', null, 'wger', 'CC-BY-SA 4', 'Original exercise instructions prepared for nalhilal', 'https://wger.de/en/exercise/2694/view/'),
  ('676e8149-863e-4174-a09a-a327b247c00d', 'Finger Pushup', 'Chest', '- Hand Positioning:
- Start in a plank position with your hands directly beneath your shoulders.
- Spread your fingers wide apart, placing them firmly on the ground.
- Finger Placement:
- Gradually lift your palms off the ground, shifting the weight onto your fingers.
- Focus on distributing the load evenly across your fingertips and thumbs.
- Body Alignment:
- Maintain a straight line from head to heels to engage your core.
- Keep your body in a controlled and stable position throughout the exercise.
- Lowering Phase:
- Slowly bend your elbows, lowering your chest towards the ground.
- Ensure controlled movement, maintaining stability on your fingertips.
- Pushing Up:
- Press through your fingertips to straighten your arms, returning to the starting position.
- Emphasize the engagement of your fingers and thumbs throughout the push-up.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/1217/view/'),
  ('0ecd5f3a-f156-4f1b-b29e-16fb80802a50', 'Fingerboard 20 mm edge', null, 'Hang for 10 seconds on a fingerboard with a 20 mm edge', null, 'wger', 'CC-BY-SA 4', 'marcelbader', 'https://wger.de/en/exercise/820/view/'),
  ('5d40cca8-ec48-4711-b97c-f744c5afabbf', 'Fire Hydrant Circles', null, 'Fire Hydrant Circles
Part of: Limber 11
Source: Joe DeFranco
Prescription: 10 forward / 10 backward
Type: dynamic', null, 'wger', 'CC-BY-SA 4', 'Pete-E automation', 'https://wger.de/en/exercise/1956/view/'),
  ('03f7fc27-e64f-4417-ab0c-a52adac60fda', 'Flat Machine Press', 'Chest', 'Execution
-
Start position:
- Elbows bent at roughly 90°, hands just outside your chest.
- Keep wrists straight and aligned with your forearms.
-
Pressing phase (concentric):
- Push the handles forward until your arms are almost fully extended — don’t lock out.
- Focus on squeezing your chest at the end of the movement.
-
Returning phase (eccentric):
- Slowly bring the handles back toward your chest, feeling the stretch in your pecs.
- Maintain tension — don’t let the weight stack touch down between reps.', 'Bench', 'wger', 'CC-BY-SA 4', 'daiben', 'https://wger.de/en/exercise/1694/view/'),
  ('32aae5db-c992-4c18-96a1-35ed03aab9a3', 'FlexBar Tyler Twist', null, 'An eccentric exercise for the wrist extensors, done with a flexible resistance bar such as a Theraband FlexBar, and widely used in rehabilitation for lateral epicondylitis (tennis elbow). Hold the bar vertically in the affected hand with the wrist extended. Grasp the top of the bar with the other hand, palm facing away, and twist the top hand to wind up the bar. Bring both arms out in front of you with the bar horizontal, then slowly let the affected wrist untwist the bar over about four seconds while the other hand holds steady. Reset and repeat. The reverse version, twisting in the opposite direction for the wrist flexors, is used for medial epicondylitis (golfer''s elbow). Move slowly and stop if the exercise causes sharp pain rather than the expected mild discomfort.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'trs1800', 'https://wger.de/en/exercise/2638/view/'),
  ('365e9101-f972-4040-9f37-26f72109fac5', 'FlexBar Wrist Extension', null, 'Performed with a flexible resistance bar such as a Theraband FlexBar. Rest your forearm on your thigh or a table with the palm facing down and the wrist just past the edge. Hold the bar in that hand, let the wrist drop, then extend the wrist to raise the bar, keeping the forearm still. Lower slowly, taking about three seconds. The resistance comes from twisting or bending the flexible bar, so a thicker or stiffer bar increases the load. Commonly used for wrist and forearm strengthening and for elbow tendon rehabilitation.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'trs1800', 'https://wger.de/en/exercise/2636/view/'),
  ('2b4dd42b-1b52-46ba-8953-82c34b309ac5', 'FlexBar Wrist Flexion', null, 'Performed with a flexible resistance bar such as a Theraband FlexBar. Rest your forearm on your thigh or a table with the palm facing up and the wrist just past the edge. Hold the bar in that hand, let the wrist extend back, then curl the wrist up to raise the bar while the forearm stays still. Lower slowly, taking about three seconds. Works the wrist flexors, and is the companion movement to FlexBar wrist extension for balanced forearm strengthening.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'trs1800', 'https://wger.de/en/exercise/2637/view/'),
  ('cf79d9fb-ffce-4648-a64f-27e4274e4c20', 'Floor dips', 'Triceps', 'Starting position:
Sit with your arms behind you, supporting your back.Your fingers should point forward.Your knees should be bent, feet together.
Steps:
- Raise your hips off the ground, straightening your arms.
- Bend your elbows, bringing your hips down.
- Straighten your arms, returning to the previous position.
- Repeat steps 2 and 3.
Notes:
The exercise''s difficulty depends on how high you bring your hips.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/1000/view/'),
  ('d6b2ac1d-4363-45e9-8fdb-9fba0a47b27d', 'Floor Glider Hamstring Curls', 'Hamstrings', 'Lie on back with heels on floor gliders or towels. Lift hips into a bridge, then slide heels toward glutes while keeping hips elevated. Slowly return to the starting position while maintaining the hip bridge.', null, 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/1833/view/'),
  ('6b68043c-a900-41f4-89fb-ea5c8193f216', 'Floor Skull Crusher', 'Triceps', 'Allowing you to safely load more weight than a regular skull crusher, lie on the floor and rest the weight on the floor in between each repetition.', 'SZ-Bar', 'wger', 'CC-BY-SA 4', 'Expenses7000', 'https://wger.de/en/exercise/1468/view/'),
  ('fdc550b6-ec58-4023-ba62-b54045e9a10d', 'Flutter Kicks', 'Obliquus externus abdominis, Abs', '-Laying on the back, lift your straightened legs from the ground at a 45 degree angle.
-As your Left foot travels downward and nearly touches the floor, your Right foot should seek to reach a 90 degree angle, or as close to one as possible.
-Bring your R foot down until it nearly touches the floor, and bring your L foot upwards.  Maintain leg rigidity throughout the exercise.  Your head should stay off the ground, supported by tightened upper abdominals.
-(L up R down, L down R up, x2)  ^v, v^, ^v, v^ = 1 rep
-Primarily works the Rectus Abdominus, the hip flexors and the lower back. Secondarily works the Obliques.  Emphasis placed on the lower quadrant of the abs.', null, 'wger', 'CC-BY-SA 4', 'nate303303', 'https://wger.de/en/exercise/235/view/'),
  ('07c5b9f4-2be5-4a3d-b6d2-16235da1ae3a', 'Fly With Cable', 'Chest', 'cable machine, two steps forward, straight back', 'Cable machine', 'wger', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/237/view/'),
  ('95d226ad-3bf7-4cd6-aa64-2f26b526d8b6', 'Fly With Dumbbells', 'Chest', 'Take two dumbbells and lay on a bench, make sure the feet are firmly on the ground and your back is not arched, but has good contact with the bench. The arms are stretched in front of you, about shoulder wide. Bend now the arms a bit and let them down with a half-circle movement to the side. Without changing the angle of the elbow bring them in a fluid movement back up.', 'Dumbbell', 'wger', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/238/view/'),
  ('55d0a5ec-b147-40c3-aa77-314e61c93689', 'Fly With Dumbbells, Decline Bench', 'Chest', 'The exercise is the same as with a regular bench:
Take two dumbbells and lay on a bench, make sure the feet are firmly on the ground and your back is not arched, but has good contact with the bench. The arms are stretched in front of you, about shoulder wide. Bend now the arms a bit and let them down with a half-circle movement to the side. Without changing the angle of the elbow bring them in a fluid movement back up.', 'Bench, Dumbbell', 'wger', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/239/view/'),
  ('46adc238-9ea9-4be4-a061-74ae50f5b7c7', 'Foam Roll IT Band', null, 'Foam Roll IT Band
Part of: Limber 11
Source: Joe DeFranco
Prescription: 10-15 passes
Type: soft_tissue', null, 'wger', 'CC-BY-SA 4', 'Pete-E automation', 'https://wger.de/en/exercise/1950/view/'),
  ('165a79bc-f4bc-4439-a0ed-6a77cd71f5e6', 'Foam Roller Adductors', null, 'Lie face down with one leg bent out to the side and the foam roller under the inner thigh. Slowly roll back and forth over your adductors with moderate pressure.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'Davidgj32', 'https://wger.de/en/exercise/1860/view/'),
  ('8a9fff1e-0908-4706-8baa-7f400e2dac19', 'Foam Roller Anterior tibialis', null, 'Slowly roll the front of your shin (tibialis anterior) over the foam roller with moderate pressure, moving back and forth.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'Davidgj32', 'https://wger.de/en/exercise/1856/view/'),
  ('164a31e9-ce70-4339-aee5-4ea7a3bdd246', 'Foam Roller Gluteus', 'Glutes', 'Sit on the foam roller and slowly roll back and forth over your glutes with moderate pressure.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'Davidgj32', 'https://wger.de/en/exercise/1859/view/'),
  ('4d96e62c-e4ac-45be-9428-b97f18ca26d9', 'Foam Roller Iliotibial band', 'Quads', 'Lie on your side with the foam roller under the outside of your thigh and slowly roll back and forth along the iliotibial band with moderate pressure.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'Davidgj32', 'https://wger.de/en/exercise/1857/view/'),
  ('b8ffa641-55e7-4761-ad5d-8336bb3ab3d4', 'Foam Roller quadriceps', 'Quads', 'Lie face down with the foam roller under your thighs and slowly roll back and forth over your quadriceps with moderate pressure.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'Davidgj32', 'https://wger.de/en/exercise/1858/view/'),
  ('17947bd2-db2d-4ba6-998c-1bbf31cf228a', 'Forearm Curls (underhand grip)', null, '- Engage the muscles
- Don''t use momentum
- Controlled movement
- Slow movement', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'Anastasious', 'https://wger.de/en/exercise/1333/view/'),
  ('9d9c4c9f-045f-4af5-adf2-8bb07c3516dc', 'Forward arm circles', null, 'Starting position:
Stand tall with your back straight.
Steps:
- Keeping your arms straight, bring them in front of you, move them down, behind your back, then over your head, and back to the initial position.
- Keep circling your arms as described in step 1.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/994/view/'),
  ('4b278f57-4505-419a-8b34-172b53eb4adc', 'Forward shoulder rotation', null, 'Starting position:
Sit or stand with your back straight.
Steps:
- Place your hands on your shoulders.
- Repeatedly rotate both shoulder joints in a circular motion at a moderate pace.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/1004/view/'),
  ('00eae665-ff78-4373-9c43-f44a4a1b43e0', 'Frog stand', 'Shoulders, Biceps, Brachialis, Abs', 'Starting position:
- Stand with your feet shoulder-width apart and your toes pointing forward, facing a wall or bench for support if needed.
- Bend your knees into a squat position.
- Place your hands on the ground in front of you, shoulder-width apart, with your fingers spread wide.
- Make sure your elbows are under your shoulders and your body forms a straight line from your head to your heels.
Upward phase:
- Push with your feet and hands to lift your body off the ground.
- Straighten your legs and arms, keeping your body aligned.
- Engage your core and glutes to maintain the position.
- If needed, rest your knees on the wall or bench for assistance.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/1238/view/'),
  ('a37001e9-b4b3-45db-8ee3-046f40350efa', 'Frog Stretch', 'Glutes', '- Get on your hands and knees.
- Widen your knees outwards, and drop to your elbows.
- Without moving your elbows or knees, start to rock forwards and backwards, trying to get your bum closer to your feet.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/1844/view/'),
  ('f41ac754-45a0-443b-afe5-e624e215229f', 'Front Lever', 'Lats, Abs', 'The front lever is a figure where the body is kept in a horizontal position parallel to the floor.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/1245/view/'),
  ('b61dff58-6e47-4671-853b-208e7cd0ced4', 'Front lever pull-up', 'Biceps, Lats, Abs', 'in the front lever position, with legs extended or easier if collected, pull by bringing the chest closer to the bar.', 'Pull-up bar', 'wger', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/1252/view/'),
  ('e79616cb-f5fb-4b10-b99d-09d43774e142', 'Front lever tuck', 'Shoulders, Biceps, Lats', 'The muscles involved in the Front Lever, most subjected to stress, are mainly the extensors such as: the latissimus dorsi, the teres major, the posterior deltoid and the long head of the biceps.', 'Pull-up bar', 'wger', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/1214/view/'),
  ('dcbfa3f0-ba88-4633-a30d-c188dccc5d3f', 'Front neck stretch', null, 'Starting position:
Sit or stand with your back straight.
Steps:
- Open mouth wide.
- Slowly tilt head back with mouth opened. If you feel the need for support, clasp your hands behind your head.
- Very slowly close and open your mouth.
- At the end, slowly return to starting position and close mouth.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/1011/view/'),
  ('dd9dcfd2-879f-422a-ad06-d2c187c58d1f', 'Front Plank', 'Abs', 'The plank is a bodyweight exercise. As a multi-functional movement, the plank not only targets your abdominal muscles but also the spine and hip. Plank strengthens and tightens your entire body, improves your posture and balance, reduces body fat, and can help boost your metabolism.
Exercises such as the “plank pose” help strengthen the stamina of stabilizing abdominal muscles. It can also help relieve back pain associated with a weakening of the function of the stabilizing muscles of the body.
Planks are a versatile exercise that targets many of the most important muscle groups in the body, so they can be applied by anyone to improve endurance and overall body strength.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'hektkaso', 'https://wger.de/en/exercise/1307/view/'),
  ('5b4b94ca-f429-4394-9477-c00be8f2bb04', 'Front Pull narrow', 'Lats', null, 'Barbell, SZ-Bar', 'wger', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/259/view/'),
  ('6260e3aa-e46b-4b4b-8ada-58bfd0922d3a', 'Front pull wide', 'Lats', null, 'Barbell, SZ-Bar', 'wger', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/258/view/'),
  ('be9dfe16-9fc3-463d-a9cd-7aade27ef571', 'Front Raise (Cable)', 'Shoulders', 'Raise the handle in a slight arc with controlled movement.
Don’t swing your torso to start the rep.', 'Cable machine', 'wger', 'CC-BY-SA 4', 'barry', 'https://wger.de/en/exercise/1731/view/'),
  ('9c35594c-bbcc-4656-bdcb-376814c90e96', 'Front Raises', 'Shoulders', 'To execute the exercise, the lifter stands with their feet shoulder width apart and weights or resistance handles held by their side with a pronated (overhand) grip.
The movement is to bring the arms up in front of the body to eye level and with only a slight bend in the elbow. This isolates the anterior deltoid muscle (front of the shoulder) and uses the anterior deltoid to lift the weight.
When lifting it is important to keep the body still so the anterior deltoid is fully utilised; if the weight cannot be lifted by standing still then it is too heavy and a lower weight is needed. It is important to keep a slight bend in the elbow when lifting as keeping the elbow locked will add stress to the elbow joint and could cause injury.
A neutral grip, similar to that used in the hammer curl, can also be used. With this variation the weight is again raised to eye level, but out to a 45 degree angle from the front of the body. This may be beneficial for those with shoulder injuries, particularly those related to the rotator cuff.', 'Barbell, Dumbbell', 'wger', 'CC-BY-SA 3', 'Manu, wikipedia', 'https://wger.de/en/exercise/256/view/'),
  ('68e0dbba-2d1e-4a56-8378-8824c1de3342', 'Front Raises with Plates', 'Shoulders, Trapezius', 'The plate front raise is a variation of the dumbbell front raise where the lifter holds a weight plate between two hands, rather than using a dumbbell, barbell, or other weight. It can provide variety in a shoulder-focused muscle-building workout, or as part of an upper body or full-body circuit.
- While standing straight, hold a barbell plate in both hands at the 3 and 9 o''clock positions. Your palms should be facing each other and your arms should be extended and locked with a slight bend at the elbows and the plate should be down near your waist in front of you as far as you can go. Tip: The arms will remain in this position throughout the exercise. This will be your starting position.
- Slowly raise the plate as you exhale until it is a little above shoulder level. Hold the contraction for a second. As you inhale, slowly lower the plate back down to the starting position.
- Repeat for the recommended amount of repetitions.', null, 'wger', 'CC-BY-SA 3', 'Marius', 'https://wger.de/en/exercise/254/view/'),
  ('d5e5c5a1-69af-42b0-9106-dc8284e7262a', 'Front Split Stretch', 'Hamstrings, Quads', '- Start kneeling.
- Extend one leg out forwards, fully straightened. Follow with your hips so your back leg begins to unfold.
- Carefully lower yourself into the stretch. Do not go beyond your limit.
- Hold for the required time.', 'Gym mat', 'wger', 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/2527/view/'),
  ('d677de4c-5bd9-412a-91f1-857116a666a2', 'Front Squats', 'Glutes', 'This variation of the squat trains the hamstrings and gluteus maximus. It also works the back extensors and abductors.', 'Barbell', 'wger', 'CC-BY-SA 3', 'sistab2', 'https://wger.de/en/exercise/257/view/'),
  ('58416166-7a3a-470d-b493-27332799dcdf', 'Front Wood Chop', null, null, null, 'wger', 'CC-BY-SA 4', 'Konsumopfer', 'https://wger.de/en/exercise/516/view/'),
  ('e5a62151-5350-4c86-8a19-3e9ca7bf0f38', 'Full Sit Outs', 'Glutes, Obliquus externus abdominis, Abs', '(A) Get in high plank position on your hands and toes.
(B) Shift your weight to your left hand as you turn your body to the right; bend your right leg behind you and extend your right arm up. Return to the center and repeat on the opposite side. Continue, alternating sides.
Make it easier: Don’t raise your arm after you bend your leg behind you.
Make it harder: Balance with your arm and leg extended for two counts.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'http://www.realsimple.com/health/fitness-exercise/', 'https://wger.de/en/exercise/260/view/'),
  ('9e3c665d-ac4e-456b-b1cd-0c209ce8090a', 'Gentle Reverse Kegels', null, 'Lie on your back with your knees bent, or sit comfortably. Breathe in slowly into your belly and let your pelvic floor relax and gently lengthen downwards, without pushing or straining. Breathe out and let the pelvic floor return to its resting position. Repeat slowly for several breaths.
The reverse Kegel trains relaxing the pelvic floor, the opposite of the contraction in a regular Kegel exercise.', null, 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/2655/view/'),
  ('ceb0c2d0-06ac-4a49-89e7-8d7b1c1e5672', 'Glute Bridge', 'Glutes', 'Lie on you back with your hips and knees flexed, feet on the ground. From this position, raise your butt off of the ground to a height where your body makes a straight line from your knees to your shoulders. To make the exercise more intense, you can add weight by letting a barbell rest on your hips as you complete the motion, or you can put your feet on a slightly higher surface such as a step or a bench.', null, 'wger', 'CC-BY-SA 4', 'tdprice12', 'https://wger.de/en/exercise/265/view/'),
  ('8c4a9c16-294b-40e5-ba6d-50ae523704ba', 'Glute Bridge Single-Arm Press', 'Chest', 'With one dumbbell in hand, perform a glute bridge. Now hold the dumbbell above your chest, this is the rep starting position. Lower the dumbbell so that your elbow touches the floor or is roughly 45 degrees below your shoulder if using a bench. Push the dumbbell back into the starting position.', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'meldun', 'https://wger.de/en/exercise/1686/view/'),
  ('ce21d3a2-cdc5-410c-9970-c25029ca3769', 'Glute Drive', 'Glutes', 'Lie down on the back pad and strap yourself in with the waistband. Position yout feet shoulder-length apart. They should be slightly splayed.', null, 'wger', 'CC-BY-SA 4', 'schweezer', 'https://wger.de/en/exercise/1528/view/'),
  ('66ed6788-a1d8-49a2-af4d-397107fbf5fb', 'Glute Kickback (Machine)', 'Glutes', 'Drive through your heel, not your toes, to hit the glute.
Don’t hyperextend your lower back at the top.', null, 'wger', 'CC-BY-SA 4', 'barry', 'https://wger.de/en/exercise/1723/view/'),
  ('537b41a8-870b-4b45-b8a5-e9672c6a359b', 'Glute-Ham Raise', 'Hamstrings', 'Kneel on a glute-ham developer or have a partner hold your ankles. Keeping hips straight, lower your torso toward the floor under control, then curl back up by contracting the hamstrings and glutes.', 'Bench', 'wger', 'CC-BY-SA 4', 'personal use', 'https://wger.de/en/exercise/2478/view/'),
  ('77a56810-d050-4083-9501-d648f773376a', 'Good Morning', 'Hamstrings', 'Stand with your feet more than shoulder-width apart (wider stance) and place your hands on your hips. Hinge at your hips and lower your upper body towards the ground while keeping your back straight then come back up.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'captive0592', 'https://wger.de/en/exercise/1392/view/'),
  ('7f942691-2a01-4675-9e3a-409105d5f2bf', 'Guided or free meditation', null, 'A mental mindfulness exercise that helps reduce anxiety, improve focus and enhance overall well-being.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'MrAlfaRobot', 'https://wger.de/en/exercise/1592/view/'),
  ('f462df26-3264-48c2-b5aa-2374d0670c24', 'Hack Squats', 'Quads', 'Hack squats target the lower body and are performed on a hack squat machine or with a barbell. For the machine variation, position yourself on the platform with your shoulders under the pads and feet slightly forward. Push through your heels to lift the weight, then bend your knees to lower the platform in a controlled motion until your thighs are parallel to the ground. Push back up to the starting position. For the barbell variation, hold the bar behind your legs with your arms extended and perform a squat-like motion.', null, 'wger', 'CC-BY-SA 4', 'hpmbala@gmail.com', 'https://wger.de/en/exercise/1414/view/'),
  ('16401732-a2cc-4493-afd6-fa70225484f6', 'Hack Squats (Custom)', 'Quads', 'Perform Hack Squats with controlled form, keeping tension on the target muscles, pausing briefly at the peak contraction, then returning slowly under control without using momentum.', null, 'wger', 'CC-BY-SA 4', 'ruochenma', 'https://wger.de/en/exercise/2717/view/'),
  ('c0d9fe98-f4fe-49f3-8037-05e1984e7d2d', 'Hammer Curls', 'Biceps', '- Start: Hold dumbbells at your sides with palms facing your torso.
- Curl: Lift the weights toward your shoulders while maintaining the neutral grip (like holding a hammer).
- Squeeze: Contract the biceps at the top without moving your elbows forward.
- Lower: Slowly return to the starting position with full control.', 'Dumbbell', 'wger', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/272/view/'),
  ('b464a133-e89d-4130-b47d-25949064aed0', 'Hammer Levering', null, 'Hold a sledgehammer or an empty dumbbell handle with a plate on one end near the bottom of the handle, arm by your side. Using only the wrist, lift the head up in front of you, then lower it slowly. Turn around so the head is behind you to train the opposite direction. Move your hand further from the weight to make it harder.', null, 'wger', 'CC-BY-SA 4', 'lightking', 'https://wger.de/en/exercise/2738/view/'),
  ('04365177-e078-489b-983a-8ac61b7346f1', 'Hammercurls on Cable', 'Biceps', 'Take a cable in your hands (palms parallel, point to each other), the body is straight. Bend the arms and bring the weight up with a fast movement. Without any pause bring it back down with a slow, controlled movement, but don''t stretch completely your arms.
Don''t swing your body during the exercise, the biceps should do all the work here. The elbows are at your side and don''t move.', 'Cable machine', 'wger', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/275/view/'),
  ('920692b2-0842-428a-b925-ba0daf6b41db', 'Hammerstrength Decline Chest Press', 'Chest', '- Sit upright in a hammerstrength decline chest press machine while squeezing your shoulder blades together and placing your heels firmly on the ground underneath your knees.
- The back pad should be contact with your head, shoulders, and butt at all times.
- Grab ahold of the handles with an overhand grip just outside shoulder-width apart just below your chest.
- Keeping your core braced by breathing into your stomach and flexing the abdominal muscles, push through your palms to extend your elbows while keeping them at a 45 degree angle from your torso.
- Once your arms are fully extended, return to the starting position.', null, 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/1831/view/'),
  ('638756b5-a957-48f4-93ca-8994cead818f', 'Hamstring Chokes', 'Hamstrings', 'Sit on the ground and bend one leg, bringing your knee toward you. Place your hand behind your hamstring and gently pull your leg toward your chest, feeling a stretch in the back of your thigh. Straighten your leg, extending up toward the ceiling.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'captive0592', 'https://wger.de/en/exercise/1398/view/'),
  ('fae5378b-db4b-4ab5-9207-07a6abab917f', 'Hamstring Foam roller', null, 'Move your hamstrings slowly over the foam roller', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'Davidgj32', 'https://wger.de/en/exercise/1855/view/'),
  ('66aef559-02e8-4f35-91f6-600f103e9cbf', 'Hamstring Kicks', 'Hamstrings', 'Stand with your feet hip-width apart and extend one arm in front of you. Swing that leg up in front of you and back down while keeping your leg as straight as possible and your toes pointed up.Repeat with the other leg.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'captive0592', 'https://wger.de/en/exercise/1387/view/'),
  ('4e238360-a4c1-4509-85c1-f96d01e69cf9', 'Hand Grip', null, 'A spring-loaded hand grip trainer for building grip strength and the forearm flexors.
- Position: hold the hand grip firmly in one hand.
- Squeeze: close it as hard as you can, trying to make the handles touch.
- Release: hold the contraction for one or two seconds, then open your hand slowly and under control, resisting the spring.', null, 'wger', 'CC-BY-SA 4', 'vince63', 'https://wger.de/en/exercise/279/view/'),
  ('0c42d72a-deb2-4f49-81c6-92763bdf1a61', 'Hand Gripper Squeeze', null, 'Hold a spring hand gripper deep in your palm. Squeeze until the handles touch, hold for a second, then open slowly. Use a gripper strength you can close for the target reps. This builds crushing grip strength for holding on in arm wrestling and in pulling exercises.', null, 'wger', 'CC-BY-SA 4', 'lightking', 'https://wger.de/en/exercise/2741/view/'),
  ('35008ce6-74ca-40db-b965-44a1eccfa061', 'Handstand', 'Shoulders', 'Handstand free standing by pressing arms into the ground and contracting core and glutes', null, 'wger', 'CC-BY-SA 4', 'Fittness69', 'https://wger.de/en/exercise/1516/view/'),
  ('7704e810-c05d-47cc-a384-265e0231a497', 'Handstand Pushup', 'Shoulders, Triceps', 'The handstand push-up (press-up) - also called the vertical push-up (press-up) or the inverted push-up (press-up) also called commandos- is a type of push-up exercise where the body is positioned in a handstand. For a true handstand, the exercise is performed free-standing, held in the air. To prepare the strength until one has built adequate balance, the feet are often placed against a wall, held by a partner, or secured in some other way from falling. Handstand pushups require significant strength, as well as balance and control if performed free-standing.', 'none (bodyweight exercise)', 'wger', 'CC0', 'BFad07', 'https://wger.de/en/exercise/282/view/'),
  ('c7a6e49c-73c2-4f83-8895-0916e05bf658', 'Hanging Leg Raise with Hip Lift on Rings (Custom)', 'Abs', 'Hang from the rings, tuck the pelvis first, then raise the legs and lift the hips, keep the torso still without swinging, lower slowly under control, breathe steadily.', 'Pull-up bar', 'wger', 'CC-BY-SA 4', 'ruochenma', 'https://wger.de/en/exercise/2756/view/'),
  ('9b993e99-8701-43f0-84d6-689123183880', 'Hanging Leg Raises', 'Abs', 'Hanging from bar or straps, bring legs up with knees extended or flexed', 'Pull-up bar', 'wger', 'CC-BY-SA 3', 'robhoyt', 'https://wger.de/en/exercise/283/view/'),
  ('785d317a-c305-4080-904e-ae775cffaf97', 'Hanging Leg Raises (Custom)', 'Abs', 'Perform Hanging Leg Raises with controlled form, keeping tension on the target muscles, pausing briefly at the peak contraction, then returning slowly under control without using momentum.', 'Pull-up bar', 'wger', 'CC-BY-SA 4', 'ruochenma', 'https://wger.de/en/exercise/2707/view/'),
  ('903bd749-3b91-4812-acd0-be7e8a012d2c', 'Happy Baby', 'Glutes', 'Lie on your back and pull your knees towards your armpits. Hold the outside of your feet, your ankles or your shins, with the soles of your feet facing the ceiling and your shins roughly vertical.
Gently pull your feet down to open the hips while keeping your lower back and head on the floor. Hold the position and breathe calmly, you can also rock gently from side to side.', null, 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/2656/view/'),
  ('36eaf240-db34-4d83-bba9-94d0e989c9e2', 'Head tilts', null, 'Starting position:
Sit or stand with your back straight.
Steps:
- Tilt your head to one side and hold for a bit.
- Return your head to neutral position and hold for a bit.
- Tilt your head to the other side and hold for a bit.
- Return your head to neutral position yet again and hold for a bit.
- Repeat.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/1018/view/'),
  ('336e224a-a7a1-4808-9871-1ad8cfc3fee7', 'Head turns', null, 'Starting position:
Sit or stand with your back straight and shoulders down.
Steps:
- Sit or stand up straight, shoulders dropped.
- Turn your head to the side as far as possible. Stop when you hit a barrier and hold for 5 seconds.
- Return to center position and repeat, changing sides.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/1007/view/'),
  ('cfe3f20e-d078-4e6c-91fc-37da62f5ac0a', 'Heel Touches', 'Obliquus externus abdominis', '-
Starting Position:
- Lie on your back on an exercise mat.
- Bend your knees, keeping your feet flat on the floor and hip-width apart.
- Place your arms along your sides, palms facing inward, just off the floor.
-
Engage Core:
- Lift your head, shoulders, and upper back slightly off the ground.
- Keep your neck neutral and chin slightly tucked.
-
Perform the Movement:
- Side-bend to the right, reaching your right hand toward your right heel.
- Return to the center, then side-bend to the left, reaching your left hand toward your left heel.
- Continue alternating sides in a controlled manner.
-
Breathing:
- Exhale as you reach toward your heel and inhale as you return to the center.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'hpmbala@gmail.com', 'https://wger.de/en/exercise/1411/view/'),
  ('e781dae5-90b8-4105-8aa6-82d278ac5ff5', 'Helms Row', 'Lats', 'Setup: Place your chest on the end of a bench, using a towel or anything soft to keep your chest protected. You want your chest to be in contact with the bench around the nipple line. Your back should be almost parallel to the floor
Execution: When you’re starting the exercise, focus on pulling your elbows back until you feel maximum tightness in the lats.
If you want to get some trap activation with the exercise, relax your shoulder blades when the weights are hanging down and then retract them as you start the rep.', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'carlos3c', 'https://wger.de/en/exercise/1303/view/'),
  ('8381f40c-3168-4d98-af60-6a89800dd308', 'Hercules Pillars', 'Biceps, Brachialis, Triceps', 'Grab two cables stand in the middle so both have tension and hold', 'Cable machine', 'wger', 'CC-BY-SA 3', 'GrosseHund', 'https://wger.de/en/exercise/284/view/'),
  ('3edbb63e-f326-4bd0-8af3-2d5deabb864f', 'High Knee Jumps', 'Hamstrings, Calves, Quads, Soleus', '- Start with legs slightly wider than shoulder width
- Drop into a bodyweight squat
- As you hit the bottom of the squat, explode upwards into a jump while simultaneously tucking your knees into your chest midflight.  Remain tucked until the apex of your jump.
- Land on both feet, making sure your knees are not locked so as to avoid excessive strain upon your joints.  Collect yourself into the next rep as quickly but under control as possible.', null, 'wger', 'CC-BY-SA 4', 'nate303303', 'https://wger.de/en/exercise/285/view/'),
  ('32942c8c-0572-4d8b-9aec-48cb026fda1f', 'High Knee Skips HD', 'Obliquus externus abdominis, Abs', 'You can use this exercise both as a dynamic warm-up before training and add it to your cardio training routine to burn fat.
High knee skips are a plyometric exercise. Plyometrics are explosive aerobic moves that increase speed, quickness, and power and they work your whole body.
High knee skips target the oblique, leg muscles, hip muscles and hip flexors and also work on the thighs, knee tendons, quadriceps and shoulders.
Jumps are beneficial to your health because they combine cardiovascular conditioning with strength work. Since jumps elevate your heart rate, they can also improve your cardiovascular fitness.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'hektkaso', 'https://wger.de/en/exercise/1318/view/'),
  ('db5bd076-2f1d-4b72-9be9-610e5c3f5724', 'High knees', null, 'Starting positionStand straight.
Steps:
- Run in place, putting knees as high up as is comfortable and switching legs at a quick pace.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/983/view/'),
  ('b2b40a54-e42b-49ec-97da-4c929ae41d42', 'High plank', 'Abs', 'Starting position:
Get into the high plank position:your hands and toes should be touching the ground, your back, arms and legs should be straight.To get to this position, you can lie down on your stomach, place your hands facing down next to your head, and lifting your arms up until they are straight.
Steps:
- Maintain the starting position for the entire duration of the exercise.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/1001/view/'),
  ('b526b17b-408d-4da2-8940-ceaf9dae9d93', 'High Pull', 'Shoulders', 'Use a light barbell, perform explosive lift up starting from underneath knee cap level. Lift/raise explosively using hips, at shoulder level. Tempo: 2111', null, 'wger', 'CC-BY-SA 3', 'Mahoney', 'https://wger.de/en/exercise/289/view/'),
  ('f80468f2-7c5d-45c5-9470-46a88c1a75c2', 'High Row', 'Lats', 'Kneeling down on one leg and pulling cable down while driving elbow into the lats.', 'Cable machine', 'wger', 'CC-BY-SA 4', 'aahuja', 'https://wger.de/en/exercise/1492/view/'),
  ('4ef75e13-c058-4410-91c0-2f2d2df98130', 'High-Cable Cross Tricep Extention - NB', 'Triceps', 'The high-cable cross tricep extension is an isolation exercise for targeting the triceps,
particularly the long head. It utilizes cables and handles grasped with opposite hands, allowing for a unique pressing motion that can be effective for building tricep strength. Unlike exercises that use a straight bar or rope, this variation can be more comfortable on your wrists and elbows', 'Cable machine', 'wger', 'CC-BY-SA 4', 'JackSparrow', 'https://wger.de/en/exercise/1298/view/'),
  ('47b244f0-ebc6-4498-9d9f-7e7bff47322e', 'High-Cable Lateral Raise', 'Shoulders', 'Stand next to a cable machine with the pulley set to waist height.
Grab the opposite-side handle with the hand farthest from the
pulley, keeping your palm facing in.
Keep your core engaged, chest lifted, and shoulders relaxed. Maintain a slight bend in the elbow throughout the lift.
Lift your arm out to the side until your elbow reaches shoulder height, keeping your wrist aligned with your elbow.
Briefly pause at the top, then slowly lower the handle back to your side with control. Repeat for the desired reps.', 'Cable machine', 'wger', 'CC-BY-SA 4', 'Deflation', 'https://wger.de/en/exercise/1882/view/'),
  ('ecba2395-f364-4e5f-a34c-04f178c8b822', 'High-Incline Smith Machine Press', 'Shoulders, Chest, Triceps', 'Set the bench to a 45-60° incline. Touch the upper chest with the bar.', null, 'wger', 'CC-BY-SA 4', 'Expenses7000', 'https://wger.de/en/exercise/1508/view/'),
  ('e87b76b8-2960-4225-9146-47f78bf8c630', 'High-pulley pullover', 'Lats, Serratus anterior', 'Stand facing the machine, feet slightly apart, gripping the bar with an overhand grip, arms extended, hands shoulder-width apart.
- Keeping your back fixed and your abdominal muscles contracted, inhale and bring the bar down to your thighs while keeping your arms extended (or your elbows slightly bent).
Exhale at the end of the movement.', 'Cable machine', 'wger', 'CC-BY-SA 4', 'Franpol', 'https://wger.de/en/exercise/1137/view/'),
  ('476c1d96-6590-4f86-98f0-3f12808fab53', 'Hindu Pushups', 'Shoulders, Chest', 'Exercise to strengthen the shoulders and pectorals. Its name is due to the fact that it begins in the Yoga position "Dog Facing Down", passing to "Cobra" but without resting the legs or torso on the ground to finally end with a normal flexion. The exercise can also be performed backwards (back to the starting position). As a variation, after doing the push-up, the hip can be raised to return to downward facing dog.', null, 'wger', 'CC-BY-SA 4', 'Imobard', 'https://wger.de/en/exercise/1080/view/'),
  ('1d610575-eed0-42cf-8737-29788a372af6', 'Hindu Squats', 'Quads', 'Start with your feet shoulder width apart and arms slightly behind your back.
As you descend towards the floor, raise your heels off the ground, while keeping your back as vertical  as possible.
Upon attaining the bottom position, touch the hands to the heels.
Then stand up ending with the heels on the ground, arms extended in front of the chest then rowing into the start position.', null, 'wger', 'CC-BY-SA 4', 'Vilhelmo', 'https://wger.de/en/exercise/291/view/'),
  ('553fb643-32f0-447f-aecb-cdf75398d742', 'Hip Airplane', 'Glutes', 'Stand on one leg and lean your upper body slightly forward while keeping your back straight. Extend the free leg behind you so that your torso and leg form roughly one line. Slowly open your hip to the side by rotating your pelvis and upper body in a controlled way. Then close the hip again and return to the starting position.
The movement should mainly come from the hip. Keep your standing foot stable and avoid letting your knee collapse inward.', 'Kettlebell', 'wger', 'CC-BY-SA 4', 'TobiasFalk', 'https://wger.de/en/exercise/2447/view/'),
  ('6b127132-cc0b-4b40-ac8c-177a28ccb6e2', 'Hip Bridge', 'Glutes, Abs', 'Get into bridge position, balance yourself on heels and start extending legs unilaterally.
Keep hip extended as much as possible.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'cybro', 'https://wger.de/en/exercise/1906/view/'),
  ('477e2c23-880b-472f-b8e2-6c9423c82fac', 'Hip Circles', null, 'View the video to undestand the exercise', null, 'wger', 'CC-BY-SA 4', 'Davidgj32', 'https://wger.de/en/exercise/1862/view/'),
  ('c8571691-f970-4486-9009-fafb77cf01b8', 'Hip Crossover', null, 'Lie on your back with your arms stretched out to the sides and your knees bent, legs together.
Slowly lower both knees to one side while keeping your shoulders and arms on the floor. You should feel a stretch in your hips, glutes and lower back.
Hold briefly, bring your knees back to the centre and repeat on the other side.', null, 'wger', 'CC-BY-SA 4', 'Davidgj32', 'https://wger.de/en/exercise/1863/view/'),
  ('0cf08c73-6af3-4852-97a5-1dff53531971', 'Hip Flexor Stretch', null, 'Kneel in a lunge position with one knee on the floor and the other foot in front, hands on your hips.
Keep your torso upright, squeeze the glute of the back leg and push your hips forward until you feel a stretch at the front of the hip and thigh. Hold, then switch sides.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'Davidgj32', 'https://wger.de/en/exercise/1867/view/'),
  ('e4c9bfde-cf06-4c24-9c56-c0bbc13c49b5', 'Hip hinge', 'Hamstrings, Glutes', 'Hip Hinge Exercise Description
The hip hinge is a fundamental movement pattern that involves bending at the hips while keeping the spine neutral. It is commonly used in exercises like deadlifts, kettlebell swings, and good mornings. To perform a hip hinge:
- Starting Position: Stand with your feet hip-width apart and a slight bend in your knees.
- Hinge at the Hips: Push your hips back while maintaining a straight back. Your torso should lean forward, and your chest should stay up.
- Lowering Phase: Continue to hinge until your torso is nearly parallel to the ground, or until you feel a stretch in your hamstrings.
- Return to Standing: Drive through your heels and thrust your hips forward to return to the starting position.', 'Barbell', 'wger', 'CC-BY-SA 4', 'mountain.potato', 'https://wger.de/en/exercise/1578/view/'),
  ('541941e0-0fa5-4474-a382-9baf04948f8d', 'Hip Raise, Lying', 'Glutes', 'Lying down on your back, with your feet flat on the floor. Raise your hips up evenly as high as you can and hold for as long as you can.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'James Mackay', 'https://wger.de/en/exercise/292/view/'),
  ('19a289c0-33af-4055-bb34-3570c2975d3d', 'Hip Thrust', 'Glutes', 'The bar should go directly on your upper thigh, directly below your crotch. Your feet should be directly under your knees. Push your hips up so that you form a straight line from your knees to your shoulders. Use a pad for comfort.', 'Barbell, Bench', 'wger', 'CC-BY-SA 4', 'Bret Contreras', 'https://wger.de/en/exercise/294/view/'),
  ('c5d0ffb9-441b-4c2d-874b-49a2d360745d', 'Hip Thrust (Custom)', 'Glutes', 'Perform the hip thrust with shoulder blades on the bench, drive through the heels, squeeze the glutes at the top for one second, avoid overextending the lower back, lower slowly.', 'Barbell', 'wger', 'CC-BY-SA 4', 'ruochenma', 'https://wger.de/en/exercise/2751/view/'),
  ('a4f78033-90d7-45a2-96fa-509b41281ea3', 'Hip-Out and Hip-In Lateral Steps', null, 'Overview of Hip-Out and Hip-In Lateral Steps
Hip-out and hip-in lateral steps are effective exercises designed to strengthen the hip abductors and enhance lateral stability. These movements are beneficial for improving coordination and overall hip function.
Exercise Descriptions
Hip-Out Steps
- Movement: Step out to the side with one leg, keeping the other leg stable.
- Target Muscles: Primarily engages the hip abductors, including the gluteus medius and minimus.
- Benefits: Increases lateral stability and strength in the hip area.
Hip-In Steps
- Movement: Bring the leg back in toward the center after stepping out.
- Target Muscles: Continues to engage the hip abductors while also activating the adductors.
- Benefits: Enhances coordination and control of the hip joint.
Key Benefits of Lateral Steps
| Benefit | Description |
|---|---|
| Strengthening Hip Abductors | Improves muscle strength around the hip joint. |
| Enhancing Stability | Increases lateral stability, reducing the risk of falls. |
| Improving Coordination | Develops better control and movement patterns in the hips. |
Incorporating hip-out and hip-in lateral steps into a regular exercise routine can lead to improved hip strength and stability, which is essential for various physical activities and daily movements.', 'Resistance band', 'wger', 'CC-BY-SA 4', 'aboksz', 'https://wger.de/en/exercise/2618/view/'),
  ('d059c63d-0a81-48a3-912a-44070c0def2e', 'Hollow Hold', 'Obliquus externus abdominis, Abs', 'Get on a mat and lie on your back. Contract your abs, stretch your arms and legs and raise them (your head and shoulders are also be raised). Make sure your lower back remains in contact with the mat.', 'Gym mat', 'wger', 'CC0', 'Behrooz', 'https://wger.de/en/exercise/297/view/'),
  ('ca4c8872-e53c-47ca-bc33-448b9ba9360f', 'Horizontal Shoulder Flexion Stretch', 'Chest', '- Raise your arm out to the side, placing your hand on a wall or doorway beside you at shoulder height
- Turn your body away from your arm to stretch the chest, as far as is comfortable', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/1712/view/'),
  ('8ccd5844-4b46-475d-b36f-5f58ca496840', 'Horizontal traction isometry', 'Lats, Chest', 'Pull yourself up on the bar until your chin is at or above bar height, and hold this position for the set time.', 'Pull-up bar', 'wger', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/1101/view/'),
  ('36411665-4a87-4ab5-b5d3-e4eaa2802a62', 'Horse Stance (Side Splits)', 'Glutes', '- Stand as for a squat, with your feet wide and your toes pointed slightly outwards.
- Gently squat into a deep, wide squat - your hips should be below your knees.
- Hold for 3 to 5 seconds.
- Come up under control, and repeat as needed.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/1846/view/'),
  ('21be14df-4114-486a-a0cf-fc604feb70c0', 'Hub Lift', null, 'Place a weight plate on the floor with the hub facing up, or use a loading pin with a plate attached. Pinch the hub with your fingertips on one side and your thumb on the other, then stand up and hold it for the set time. This builds thumb and pinch strength, which helps grip control in arm wrestling.', null, 'wger', 'CC-BY-SA 4', 'lightking', 'https://wger.de/en/exercise/2743/view/'),
  ('ebe7d74b-78a8-4757-9310-6fb22b23aa58', 'Hyper Y W Combo', 'Lats', '- Use a glute-ham raise or a
stability ball for this exercise and a light weight plate in each hand.
- Raise your torso to form a straight line with your legs and raise the
arms outward slightly beyond a 90-degree angle into a W position to hit
the rotator cuff muscles, and then lower back to the starting position.
- Then raise up again with arms
in a Y position to activate the lower traps.', null, 'wger', 'CC-BY-SA 4', 'Moffi', 'https://wger.de/en/exercise/1487/view/'),
  ('37f6bd56-815a-4975-99af-05e749fae4b2', 'Hyperextensions', 'Trapezius', 'Lie on the hyperextension pillow with your navel at the front edge, allowing your upper body to hang freely. Tighten all your back muscles and raise your torso until you''re horizontal, but no higher. Lower yourself slowly, maintaining a steady flow of muscles.', null, 'wger', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/301/view/'),
  ('662b9911-fa55-4564-b830-fdb6a046b162', 'Ice cream maker', 'Lats', 'From the final phase of a pull-up, we push ourselves back with our shoulders until we reach the front lever position. From there, we pull ourselves back up to the starting position.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/1248/view/'),
  ('275fb49f-975c-4d6e-9d63-2c86ed740f40', 'Incline Bench Press - Barbell', 'Chest', 'To do slowly, tempo is 4010', 'Barbell, Incline bench', 'wger', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/538/view/'),
  ('57e17672-52b9-43cf-8d0d-4b3f06a0c0d0', 'Incline Bench Press - Dumbbell', 'Chest', 'This is a variation of the flat bench press designed to emphasize the clavicular head of the pectoralis major (the upper portion). By tilting the torso, the angle of the push changes, shifting more tension to the upper chest and shoulders, which helps achieve a more aesthetic, balanced, and three-dimensional development of the torso.
-
Bench Adjustment and Preparation: Set the bench to an incline of between 30 and 45 degrees (an incline greater than 45° will place too much strain on the shoulders and reduce the stimulus to the chest). Sit down with a dumbbell on each thigh.
-
Starting position: Lean back, resting your back against the bench, while using your knees one after the other to push the dumbbells upward to shoulder height.
-
Anatomical Stabilization: Plant your feet firmly on the floor. Retract your scapulas (bring your shoulder blades together and press them into the bench) to protect your shoulders and stabilize the load.
-
Eccentric Phase (Lowering): Lower the dumbbells slowly and in a controlled manner toward the upper part of your chest. Your elbows should not splay out to the sides (90°); maintain a safe angle of about 45 to 60 degrees relative to your torso.
-
Concentric Phase (Lift): Push the dumbbells vertically upward as you exhale. Follow a slightly converging path (without letting them touch at the top). Stop the movement just before locking out your elbows to maintain muscle tension in the upper pectoral.', 'Dumbbell, Incline bench', 'wger', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/537/view/'),
  ('60e9a0c0-5458-46cd-ab41-7d7b85225cf8', 'Incline Bench Press - MP', 'Chest', null, null, 'wger', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/539/view/'),
  ('4e941b0d-4b2f-4393-89cf-6a5e9b69252e', 'Incline bench pulldown', 'Lats', 'Lying face down on the incline bench facing the cable machine, perform the pulldown.', 'Cable machine', 'wger', 'CC-BY-SA 4', 'Franpol', 'https://wger.de/en/exercise/1138/view/'),
  ('70c99a4e-3340-4993-a7f1-2d2709dada1a', 'Incline Bench Reverse Fly', 'Shoulders, Trapezius', 'The incline dumbbell reverse fly is an upper-body exercise targeting the posterior or rear deltoids, as well as the postural muscles of the upper back. Because it targets such small muscles, this exercise is usually performed with light weight for high reps, such as 10-15 reps per set or more.', 'Dumbbell, Incline bench', 'wger', 'CC-BY-SA 4', 'cshep442', 'https://wger.de/en/exercise/828/view/'),
  ('51a2d520-b510-4b6e-bd65-9fc40365e8de', 'Incline Chest-Supported Dumbbell Row', 'Biceps, Lats, Trapezius', '- Set up an adjustable bench at a 45-degree angle.
- Lay on your stomach with your head hanging just above the edge of the bench.
- Grab a dumbbell in each hand and set up with a good posture – core and lats engaged and shoulders neutral.
- Row the dumbbells toward the top of the stomach and squeeze the back at the top of the rep.
- Finally, lower the dumbbells back to the starting position and repeat until all reps are completed.', 'Bench, Dumbbell', 'wger', 'CC-BY-SA 4', 'carlos3c', 'https://wger.de/en/exercise/1283/view/'),
  ('fca05168-7212-42ec-8927-efb1e8dd0971', 'Incline Close Grip Barbell Bench Press', 'Triceps', 'Narrower grip than regular bench press, just outside shoulder width.', 'Barbell', 'wger', 'CC-BY-SA 4', 'Expenses7000', 'https://wger.de/en/exercise/1467/view/'),
  ('7de7b8a8-313d-465f-bb22-8527ae45110a', 'Incline Crunches', 'Abs', 'Lay down on your back on a inclined bench, feet are on one end of the bench. Ask a partner or use some other help (barbell, etc.) to keep them fixed, your hands are behind your head. From this position move your upper body up till your head or elbows touch your knees. Do this movement by rolling up your back.', 'Incline bench', 'wger', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/171/view/'),
  ('16bd91ca-a9fe-47fc-b3a8-a9d70549e929', 'Incline DB Y-Raise', 'Shoulders', '- Set
an incline bench to a 45-degree angle and sit facing the bench, chest
against the pad, with a dumbbell in each hand, palms facing each other.
- Position your feet firmly on the ground for stability and let your arms hang down naturally with a slight bend in your elbows.
- Engage your core and keep your back straight throughout the movement.
- Raise your arms forward and out to form a Y shape, keeping the movement controlled and your elbows slightly bent.
- Lift until your arms are roughly parallel to the floor and in line with your ears.
- Pause
briefly at the top of the movement to engage your shoulder muscles
fully, then slowly lower your arms back down to the starting position.
- Ensure
the movement is slow and controlled during both the ascent and descent
to maximize engagement of the deltoids and supporting muscles.
- Repeat for the desired number of repetitions, maintaining proper form throughout.', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'Deflation', 'https://wger.de/en/exercise/1879/view/'),
  ('6d29310c-b7d7-4e4f-9232-eb3c19a56aff', 'Incline DB Y-Raise (Custom)', 'Shoulders', 'Perform Incline DB Y-Raise with controlled form, keeping tension on the target muscles, pausing briefly at the peak contraction, then returning slowly under control without using momentum.', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'ruochenma', 'https://wger.de/en/exercise/2721/view/'),
  ('55ff32e6-24ab-4303-9b50-176d60d48796', 'Incline Dumbbell Fly', 'Chest', 'Use inclined bench. Hold dumbbells straight out to your sides, elbows slightly bent. Bring arms together above you, keeping angle of elbows fixed.', 'Dumbbell, Incline bench', 'wger', 'CC-BY-SA 3', 'tuckerm', 'https://wger.de/en/exercise/308/view/'),
  ('27eb3d4a-8677-4c1f-bf34-251e2b4741cb', 'Incline Dumbbell Row', null, '- Using a neutral grip, lean into an incline bench.
- Take a dumbbell in each hand with a neutral grip, beginning with the arms straight. This will be your starting position.
- Retract the shoulder blades and flex the elbows to row the dumbbells to your side.
- Pause at the top of the motion, and then return to the starting position.', 'Dumbbell, Incline bench', 'wger', 'CC-BY-SA 4', 'cal.zabel', 'https://wger.de/en/exercise/310/view/'),
  ('f89b3662-f911-4aab-9402-cfa6d47cea2b', 'Incline OHP DB', 'Shoulders', '- Sit on a bench with 45° incline
- Ellbows 45° out
- Move dumbbells down until upper arms are parallel to shoulders
- Move dumbbells up, meeting overhead', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'M9', 'https://wger.de/en/exercise/1441/view/'),
  ('aae91ecf-ffa4-4730-812c-cb00e423f91c', 'Incline Plank With Alternate Floor Touch', 'Abs', 'Perform the plank with legs elevated, feet on a gymball. Once stabilised, slowly move one foot sideways off the ball, then make it touch the floor, then come back to starting position. Alternate with the other foot.
This is a core exercise.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 3', 'Mahoney', 'https://wger.de/en/exercise/312/view/'),
  ('e1a4c2a6-d4ed-4550-b37e-dc0078d96c64', 'Incline Row - Rings', 'Shoulders, Biceps, Lats, Trapezius', 'Perform a row using gymnastic rings, but with the body position somewhere between vertical and horizontal. Go closer to horizontal to make it harder.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'wintercyan', 'https://wger.de/en/exercise/2678/view/'),
  ('743690d3-dbfb-417a-a049-8b77fd5df31b', 'Incline Shoulder Press Up', 'Shoulders, Chest', '- Place your hands on the bench in a press up position
- Push your chest away from the bench to separate your shoulder blades
- Keeping your elbows straight, lower your chest towards the bench so your shoulder blades move closer together
- Push your chest away from the bench again', 'Bench', 'wger', 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/1716/view/'),
  ('76a2f8a6-374b-42c8-b8ac-e8d64612f046', 'Incline Skull Crush', 'Triceps', 'Siting in a 45 Degree Angle, using DB to do Incline Skull Crush', null, 'wger', 'CC-BY-SA 4', 'novadani', 'https://wger.de/en/exercise/911/view/'),
  ('88afb956-8d4a-45b3-8c7c-c23719316bfe', 'Incline Static Hold', 'Chest', 'Execution
-
Hold Position:
- Lower the dumbbells a few inches above your chest — about the midpoint of a normal incline press.
- This is where your upper chest is under maximum tension.
-
Static Hold:
- Hold the position for 20–45 seconds while keeping the chest tight.
- Breathe slowly but stay tense — do not relax your chest or shoulders.
-
End the set:
- After the hold, carefully bring the dumbbells down and rest.', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'daiben', 'https://wger.de/en/exercise/1693/view/'),
  ('1639425c-7dc6-4776-b039-47ef14a328ee', 'Inverted Lat Pull Down', 'Lats, Trapezius', 'The Inverted Lat Pull Down (most commonly known as the Reverse Grip Lat Pull Down) is a variation of the standard exercise that uses an underhand (supinated) grip with hands at shoulder-width. This position shifts more emphasis to the lower lats and increases biceps involvement, often allowing for a greater range of motion and a deeper squeeze at the bottom of the movement.', 'Pull-up bar', 'wger', 'CC-BY-SA 4', 'amaesc', 'https://wger.de/en/exercise/1927/view/'),
  ('8d56eb18-b000-41ff-8b31-c74df3a4b34b', 'Inverted Rows', 'Biceps, Lats', 'Maintain a straight body, retract your shoulder blades, and pull your
chest to the bar for an effective back and upper body workout.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'Gavru', 'https://wger.de/en/exercise/1198/view/'),
  ('7a1e0cd7-0076-4d4d-b05f-1d114235f199', 'Isometria alle parallele', 'Chest, Trapezius', 'The parallel bars isometric hold is a static upper-body exercise performed on dip bars (parallel bars). Instead of moving up and down like in a traditional dip, you hold a fixed position under tension.', null, 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/1914/view/'),
  ('75c35f50-ed04-48a5-872b-0251e0bf27b5', 'Isometric Dumbbell Pronation Hold', null, 'Rest your forearm on a bench with the palm facing in and the thumb on top. Hold a dumbbell by one end with the weighted end pointing up. Let the weight tip about 45 degrees toward the palm up side, then stop it and hold that position for the set time. The muscles that stop it falling are your pronators, which roll the hand over in arm wrestling. Start with a light weight because the leverage is high.', 'Bench, Dumbbell', 'wger', 'CC-BY-SA 4', 'lightking', 'https://wger.de/en/exercise/2728/view/'),
  ('06cb77ba-e56d-4422-bc14-77cc367c9fd8', 'Isometric Squat to Failure', 'Glutes, Quads', 'sometric Squat to Failure: A Strength Training Technique
Definition
The isometric squat to failure is a variation of the squat exercise where you hold a static squat position at a specific angle, maintaining the position until your muscles can no longer sustain the contraction.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'Tierrasverdes', 'https://wger.de/en/exercise/1733/view/'),
  ('2f5032de-df6d-406b-b709-9223ef5c3e24', 'Isometric Wipers', 'Chest', 'Assume push-up position, with hands slightly wider than shoulder width.
Shift body weight as far as possible to one side, allowing the elbow on that side to flex.
Reverse the motion, moving completely over to the other side.
Return to the starting position, and repeat for the desired number of repetitions.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'cal.zabel', 'https://wger.de/en/exercise/314/view/'),
  ('2d63b52a-464c-415f-96b4-daa1d4bc09e0', 'Isometric Wrist Curl Hold', null, 'Sit on a bench with your forearm resting on your thigh, palm facing up, holding a dumbbell or barbell. Curl the wrist all the way up and hold the top position for the set time, squeezing hard. This builds cupping strength and tendon resilience for grip and arm wrestling. Do it straight after your wrist curls without changing seats.', 'Bench, Dumbbell', 'wger', 'CC-BY-SA 4', 'lightking', 'https://wger.de/en/exercise/2729/view/'),
  ('e3fc2aac-6bcc-4969-bd66-f907e11fea47', 'Isometric Wrist Rising Hold', null, 'Set up exactly as for dumbbell wrist rising: arm straight down by your side, dumbbell held at one end with the weight pointing forward. Tip the weight up to the top position and hold it still for the set time without letting it drop. This builds tendon strength in the riser for arm wrestling. Start light and stop if you feel sharp pain in the wrist or elbow.', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'lightking', 'https://wger.de/en/exercise/2726/view/'),
  ('c9de4551-f1bc-4490-98f4-c9f87c2a2cac', 'Jalón al pecho con agarre ancho', 'Lats, Trapezius', 'The lat pulldown is a pulling exercise that primarily targets the latissimus dorsi muscles (commonly known as “lats”) in your back. It involves pulling a cable bar or handle down towards your chest while seated on a machine specifically designed for this exercise. The lat pulldown is typically performed with a wide grip, but can also be done with a narrow grip or underhand grip to target different muscle groups in the back and arms. It is a popular exercise for building upper body strength and improving posture.', 'Cable machine', 'wger', 'CC-BY-SA 4', 'Mariano_O', 'https://wger.de/en/exercise/1702/view/'),
  ('85c28424-ab47-40d4-9a27-e1b9bfb01e7c', 'Jerk OL', 'Shoulders', 'Olympic lift jerk
- Hold bar in front on shoulders like push press
- Bend and extend knees pushing bar up while diving under the bar
- Catch bar overhead with straight arms using lunge
- Move feet parallel while holding bar in lockout', 'Barbell', 'wger', 'CC-BY-SA 4', 'M9', 'https://wger.de/en/exercise/1445/view/'),
  ('67c2fe41-f1e9-4f75-b2cb-72d1f2e092f7', 'JM Press', 'Triceps', 'The JM press keeps your shoulders stationary, relying on the elbow flexion and extension to move the weight using your triceps strength. That means you get all the benefits of the best triceps-strengthening exercises without overtaxing that delicate shoulder joint. Classic win-win!', 'Barbell', 'wger', 'CC-BY-SA 4', 'Epiphany8424', 'https://wger.de/en/exercise/1302/view/'),
  ('eeeb42ae-6a41-4127-b2ec-72376119531b', 'Jogging', null, 'Get your shoes on, go outside and start running at a moderate pace.', null, 'wger', 'CC-BY-SA 4', 'Papazit', 'https://wger.de/en/exercise/319/view/'),
  ('cd51aa2a-52b3-43df-8011-0c8ef4b7ed11', 'Jump rope: basic jumps', null, 'Starting position:
Put your feet close together, bend the knees a bit, keep your head and body straight, keep elbows in, open your arms.
Steps:
- Spin only your wrists with enough force to make the rope spin.
- Jump just high enough to pass the rope below your feet.
- Repeat.
Notes:
This exercise requires a jump rope. Make sure the rope length is adjusted to your height. One way to check is to grab both handles with one hand and stand on the middle of the rope hanging on the ground with one foot. If the rope (excluding the handles) reaches just below your chest, its length is right. A shorter rope would be hazardous, as you might hit yourself, and a longer rope would make for bad form.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/993/view/'),
  ('89443e49-e5be-4b67-a5f6-e3f5ff80f6ea', 'Jumping Jack HD', 'Quads', 'Jumping jack are a plyometric exercise. Plyometrics are explosive aerobic moves that increase speed, quickness, and power and they work your whole body.
Jumping jack target the arm, shoulder, abdominal muscles, hip muscles and hip flexors and also work on the thighs, knee tendons and quadriceps.
Jumps are beneficial to your health because they combine cardiovascular conditioning with strength work. Since jumps elevate your heart rate, they can also improve your cardiovascular fitness.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'hektkaso', 'https://wger.de/en/exercise/1314/view/'),
  ('4d255f25-f199-401a-bc81-7ffab1d0ed24', 'Jumping Jacks', 'Quads', 'A jumping jack or star jump, also called side-straddle hop in the US military, is a physical jumping exercise performed by jumping to a position with the legs spread wide and the hands going overhead, sometimes in a clap, and then returning to a position with the feet together and the arms at the sides', null, 'wger', 'CC-BY-SA 4', 'student1234', 'https://wger.de/en/exercise/320/view/'),
  ('8b60bc5c-ced8-4e49-9b0e-a581d51fc66a', 'Jumping Pull-Up', 'Lats', 'Stand under a pull-up bar on the floor or a low box so you can reach the bar with bent arms. Jump and pull at the same time until your chin passes the bar, then lower yourself as slowly as you can. This is a beginner step toward full pull-ups.', 'Pull-up bar', 'wger', 'CC-BY-SA 4', 'lightking', 'https://wger.de/en/exercise/2748/view/'),
  ('5597bafc-0478-4124-9745-85f9df22be3e', 'Kegel Exercise', null, 'Lie on your back with your knees bent, or sit upright in a chair. Locate the pelvic floor muscles: they are the muscles you would use to stop the flow of urine or to hold back gas. Keep your abdomen, glutes and thighs relaxed and breathe normally throughout.
Tighten the pelvic floor muscles and lift them gently upwards and inwards. Hold the contraction for a few seconds, then release completely and rest for at least as long as you held. Repeat for the desired number of repetitions.
The exercise can be varied by holding longer with a light contraction (endurance) or by performing quick, short contractions with a full relaxation in between.', null, 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/2555/view/'),
  ('11914fdd-02d9-4aa6-88be-0c10cd54c609', 'Kelso Shrugs', 'Trapezius', 'Kelso shrugs are a variation of scapular shrugs designed primarily to train scapular retraction, with particular emphasis on the middle trapezius, rhomboids, and, secondarily, the lower trapezius. Unlike conventional shrugs, the goal is not to elevate the shoulders toward the ears, but rather to pull the shoulder blades backward.
They are typically performed with the chest supported on an incline bench, using either dumbbells or a barbell:
- Lie face down on an incline bench, with your arms extended toward the floor.
- Keep your elbows almost completely locked throughout the movement.
- Starting with the shoulder blades slightly protracted, retract them, trying to bring them closer together.
- Keep your chest firmly supported on the bench; avoid turning the movement into a row by extending your torso.
- Briefly hold the fully retracted position, then return in a controlled manner, allowing the shoulder blades to separate.', 'Barbell, Bench', 'wger', 'CC-BY-SA 4', 'Friend7857', 'https://wger.de/en/exercise/2672/view/'),
  ('9b5f8c6e-2436-4ded-aea9-8c698b0c8768', 'Kettlebell deadlifts', 'Hamstrings, Glutes', 'Starting position:
Stand hip-width apart, with your kettlebell centered between your ankles. Your back should be straight, your head facing forward.
Steps:
- Hinge at the hips and slightly bend at the knees to put your hands on the kettlebell handles. Your back should be straight as you perform the movement.
- Grab the kettlebell handles, with your hands pushing in opposite directions as if to pull the handle apart.
- While contacting your abs and glutes, stand straight up.
- Hinge at the hips again to bring the kettlebell back down, similarly to step 1.
- Repeat from step 3.
Tips:
- Be sure you''re performing the movements correctly, as doing otherwise can lead to injury. For example, do not squat instead of hinging at the hips, do not round your back while reaching for the kettlebell, and do not lean back while standing up.', 'Kettlebell', 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/1003/view/'),
  ('20b17b71-6d91-4b56-978a-04b7f94c04cc', 'Kettlebell One Legged Deadlift', 'Glutes', 'This exercise involves holding a kettlebell in one hand and standing on one leg while bending forward to touch the kettlebell to the ground. It targets the hamstrings, glutes, and lower back while also improving balance and stability.', 'Dumbbell, Kettlebell', 'wger', 'CC-BY-SA 4', 'AlucardEvil40', 'https://wger.de/en/exercise/1641/view/'),
  ('5cbaa028-114d-4a15-9a95-70d9b3146f30', 'kettlebell sumo deadlift', 'Hamstrings, Glutes, Quads', 'Place your feet wider than shoulder-width apart, pointing your toes outward.
Keep your back straight, shoulders back, and chest up.
The knees must follow the same direction as the toes and not move forward.
When going up, it is advisable to contract your glutes to maximize the effectiveness of the exercise..', 'Kettlebell', 'wger', 'CC-BY-SA 4', 'Tierrasverdes', 'https://wger.de/en/exercise/1612/view/'),
  ('03960339-fe14-4670-a7b3-4974b859ed37', 'Kettlebell sumo high pull', 'Trapezius', 'A compound exercise combining elements of a sumo deadlift and a high pull. It targets the posterior chain, particularly the glutes, hamstrings, and upper back. The sumo stance increases hip engagement, while the high pull adds an explosive element, promoting power development.
- Stand upright overtop of a kettlebell with your feet wider than shoulder-width apart angled out slightly.
- Maintain a braced core and neutral spine throughout the exercise.
- Hinge your hips backward and extend your arms to grab ahold the kettlebell with a double overhand grip.
- With you lower legs nearly vertical to the ground, extend your hips to raise the kettlebell with your elbows high keeping it close to your body.
- Once the kettlebell has reached shoulder height, lower back to the starting position.', 'Kettlebell', 'wger', 'CC-BY-SA 4', 'wgerpott', 'https://wger.de/en/exercise/1970/view/'),
  ('d813ef7c-b10a-4c5c-ba55-6b9518e7ff4c', 'Kettlebell Swing', 'Shoulders, Glutes', 'While kettlebell swings are a full-body workout, they mostly target the muscles along the posterior chain (back of the body). The main muscles used are the glutes, hamstrings, spinal erectors, and muscles of the upper back.', 'Kettlebell', 'wger', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/960/view/'),
  ('8b311259-4f67-4dbf-9574-8c38faa92160', 'Kettlebell Swings', 'Glutes', 'Hold the kettlebell securely in both hands. Keep your back flat throughout the move, avoiding any rounding of the spine.Keeping your knees "soft", hinge your hips backwards, letting the kettlebell swing between your knees.
You want to bend from the hips as far as you can without letting your back round forwards. Then, snap your hips forwards quickly and standing up straight, locking your body in an upright posture.
The speed you do this will cause your arms and the kettlebell to swing up in front of you. Don''t try to lift the kettlebell with your arms. The snapping forwards of your hips will cause the kettlebell to swing forwards through momentum. Depending on the weight of the kettlebell and the speed of your hip movement, your arms will swing up to about shoulder height. At the top of this swing, let your hips hinge backwards again as the kettlebell swings back down to between your legs and the start of the next repetition.', 'Kettlebell', 'wger', 'CC-BY-SA 3', 'J120290,cerin', 'https://wger.de/en/exercise/331/view/'),
  ('a650d15d-762a-4dcb-b017-10b15f2483a5', 'Kettlebell Wrist Turnover', null, 'Rest your forearm on a bench or your knee and hold a light kettlebell by the handle with the bell hanging down. Keeping the elbow and forearm still, slowly rotate your wrist so the palm turns down, then rotate back so the palm turns up. Do the set number of turns in each direction. This trains pronation and supination for grip and arm wrestling.', 'Bench, Kettlebell', 'wger', 'CC-BY-SA 4', 'lightking', 'https://wger.de/en/exercise/2727/view/'),
  ('57d1a6fc-fc28-43a7-9beb-0e851a47a976', 'Kick with Board', 'Glutes, Quads', 'Hold a kickboard with both hands, arms extended in front of you, face in the water (lift head forward to breathe when needed). Kick from your hips, not your knees, keeping your legs mostly straight with a slight bend and a steady, compact flutter kick. This builds leg endurance and keeps your body horizontal without needing to worry about your arms.', null, 'wger', 'CC-BY-SA 4', 'Imported from swim plan', 'https://wger.de/en/exercise/2481/view/'),
  ('107ea68a-d976-49ed-be75-3b0cf253c36a', 'Kickstand RDL', 'Hamstrings', 'use non-working leg''s toes to help with balance and perform an RDL.', 'Barbell', 'wger', 'CC-BY-SA 4', 'eriktrinkle', 'https://wger.de/en/exercise/1688/view/'),
  ('2b61df61-f71e-4b8f-9f95-6a565238a8ae', 'knee push-ups', 'Shoulders, Chest', '- Start by kneeling on the floor, keeping your knees together. Place your hands on the floor in front of you, slightly wider than shoulder-width apart.
- Make sure your body forms a straight line from head to knees. Hands should be positioned below shoulders.
- Lower your torso towards the ground, bending your elbows while keeping your trunk stable. Keep your knees in contact with the floor.
- Push through your hands to return to the starting position. Be sure to maintain contraction of chest, shoulder and arm muscles at the top of the movement.
- Perform the desired number of repetitions, controlling the movement and maintaining good form.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'PaukOne', 'https://wger.de/en/exercise/1218/view/'),
  ('f4991a98-6422-4884-8ad3-43412f91fac1', 'Knee Raises', 'Abs', 'The 90° leg raise on the bar is a very intense exercise that involves all the abdominal muscles.', 'Pull-up bar', 'wger', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/978/view/'),
  ('492e90a5-1ecb-4a06-8e9d-26a00042560e', 'Knee to Chest Stretch', 'Glutes', 'The knee to chest stretch is a simple yet effective exercise for relieving lower back tension and improving hip mobility. To perform, lie flat on your back with your legs extended. Bring one knee toward your chest, wrapping your hands around your shin or behind your thigh. Gently pull the knee closer to your chest while keeping the other leg straight on the floor. Hold the stretch for 15–30 seconds, then switch sides. For a deeper stretch, both knees can be pulled toward the chest simultaneously.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'hpmbala@gmail.com', 'https://wger.de/en/exercise/1452/view/'),
  ('6ddea666-5a57-4ac0-926f-01f8cfdaa4fd', 'Kneeling kickbacks', 'Glutes', 'Starting position:
Get down on all fours.
Steps:
- Push one foot back until fully extended, concentrating on the gluteus muscles.
- Stay for one second, then return to the initial position.
- Repeat, alternating feet.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/990/view/'),
  ('00f4a2b1-b1ac-49e6-a657-1d27e46522fd', 'Kneeling Superman', 'Hamstrings, Trapezius', '-
Push one foot back until leg fully extended, concentrating on the having the foot high and pushed back as if pulled.
-
Extend arm forward with focus having the shoulder high up.
Unilateral and static hold.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'cybro', 'https://wger.de/en/exercise/1910/view/'),
  ('329d2adc-4b2c-4bb2-95d7-f5f6fedb9b96', 'Kong Curl', 'Biceps', 'This exercise is somewhat similar to a cable curl and a cable crossover. But instead of a chest/biceps exercise, this exercise targets the brachialis muscle, responsible for that broad arm when viewed from a front view.
During the exercise, maintain a pronated forearm position with starting position of approx. 45 degree pronated. Start with slightly bend elbows and alternately curl until your hands (your thumb first) meet your upper middle chest (similar to how Kong hits his chest, thus the name of this exercise).', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'Moffi', 'https://wger.de/en/exercise/1511/view/'),
  ('b4e78b5a-6141-4fc9-a6f7-cba13ce6559b', 'Kreis Press DB', 'Shoulders', '- Sit on a bench with 45° incline
- Hold dumbbells overhead
- Move dumbbells down as if doing overhead press
- Rotate dumbbells palms facing up and extend your arms in front of your body
- Move hands together until dumbbells meet, keep arms extended
- Reverse the motion until dumbbells are overhead again
- This is one repetition', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'M9', 'https://wger.de/en/exercise/1442/view/'),
  ('84b38ac6-9628-4f80-8940-204047fa2544', 'Kroc Row', 'Lats, Trapezius', 'Dumbbell rows with looser technique but heavier weight.', null, 'wger', 'CC-BY-SA 4', 'Expenses7000', 'https://wger.de/en/exercise/1471/view/'),
  ('16089e03-5afc-4a18-a40a-beb337806ac0', 'L Hold', null, 'Hold the L position for as long as possible', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 3', 'bizyguy', 'https://wger.de/en/exercise/382/view/'),
  ('16202754-f567-4d23-a866-2c9cc8eba71d', 'L-sit', 'Lats, Chest, Abs', 'Sit on the ground with your legs together and your arms by your sides. Push your body off the ground using your hands, maintaining the same sitting position so that your legs are straight and your feet do not touch the floor.
Hold for as long as required.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/1852/view/'),
  ('a092afaf-aa5a-4384-b407-a6b52cf1c008', 'L-Sit (Foot Supported)', 'Lats, Chest, Abs, Serratus anterior', 'As with an L-sit, but allow your feet to touch the floor to support the some of the weight of your legs.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/1853/view/'),
  ('547217ec-cb9e-4713-8bab-2d8bfb160667', 'L-Sit Pull-ups', 'Lats', 'Pull-ups performed with your legs held straight out in front of you, so that your body forms an L. Trains both the upper body and the core.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'Happy', 'https://wger.de/en/exercise/1741/view/'),
  ('91c47c8b-6290-4885-8921-df9aa7958c00', 'Landmine press', 'Shoulders', null, 'Barbell', 'wger', 'CC-BY-SA 4', 'Torsten Linnecke', 'https://wger.de/en/exercise/346/view/'),
  ('73c1e130-fba9-473b-a093-a5712e2ae34d', 'Landmine Rotation', 'Obliquus externus abdominis', 'Start with landmine barbell straight up by using your shoulders to push it up above you. Then, from that position, bring it your side to target your abdominals and return to starting position.', 'Barbell', 'wger', 'CC-BY-SA 4', 'aboksz', 'https://wger.de/en/exercise/1779/view/'),
  ('67bca611-d9f1-4855-9e02-ecc8d7d688e9', 'Landmine Squat to Press', 'Shoulders, Glutes, Quads', '-
Bar Position: Anchor one end of a barbell in a landmine attachment or a secure corner.
-
Stance: Stand facing the barbell with feet slightly wider than shoulder-width. Turn your toes out 10–35 degrees to allow for better pelvic movement and depth.
-
Grip: Cup the free end of the barbell with both hands (fingers interlaced or overlapping) and hold it at mid-chest level, just below the collarbone.
-
Descent: Brace your core and sit back into a squat, keeping your chest up and weight on your heels.
-
Depth: Lower until your thighs are at least parallel to the floor. A good reference is when your elbows touch the tops of your thighs or just inside your knees.
-
Posture: Ensure your back remains flat and your spine neutral throughout the movement.
-
Drive: Powerfully drive through your heels to stand up. Use the momentum from your legs to "thrust" the weight upward.
-
Extension: In one fluid motion, press the bar overhead until your arms are fully extended. At the top, your biceps should be near your ears.
-
The "Lean": As you reach the top of the press, lean slightly forward into the bar to encourage proper upward rotation of the shoulder blades and avoid lower back arching.
Slowly lower the barbell back to chest height in a controlled manner before immediately beginning the next repetition.', 'Barbell', 'wger', 'CC-BY-SA 4', 'beagle', 'https://wger.de/en/exercise/1829/view/'),
  ('87f30f6d-dc8a-4b26-8c4f-640b66ecacf0', 'Larsen Press', 'Chest', 'Put your legs up on a separate Bench and press with no leg drive', 'Barbell', 'wger', 'CC-BY-SA 4', 'Expenses7000', 'https://wger.de/en/exercise/1546/view/'),
  ('90dea8b9-4cf8-430e-8633-e08df1dd900b', 'Lat Pull DB', 'Lats', '- Bend upper body forward
- Move dumbbells near your body with slightly bent arms towards your back', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'M9', 'https://wger.de/en/exercise/1434/view/'),
  ('8c496646-baa8-4ed3-97b1-702e213fdeca', 'Lat Pull Down (Leaning Back)', 'Lats', 'Lean Back, Pull into chest', null, 'wger', 'CC-BY-SA 3', 'drthurlow', 'https://wger.de/en/exercise/354/view/'),
  ('fff05d7a-f374-4c8a-9885-39f49076918f', 'Lat Pull Down (Straight Back)', 'Lats', 'The lat pull down is an exercise used to build the muscles of the back. While the exercise will primarily target the lats, you will also notice a fair amount of bicep and middle back activation.', null, 'wger', 'CC-BY-SA 3', 'drthurlow', 'https://wger.de/en/exercise/355/view/'),
  ('5a096571-4eae-472e-8849-fe5647035e2c', 'Lat Pulldown - Cross Body Single Arm', 'Lats', 'Sit at lat pulldown machine with body at a diagonal angle so that only one leg is under the pad. Pull the cable down with the opposite arm. this will force the cable to across your body while pulling down. Emphasises the stretch of the lat.', 'Cable machine', 'wger', 'CC-BY-SA 4', 'Shiladree', 'https://wger.de/en/exercise/1659/view/'),
  ('b6054509-576f-429c-960f-73c84f481b7c', 'Lat Pulldown Isometric', 'Lats', 'An isometric Lat pulldown is a strength-building exercise where you pull the bar down to your chest and hold the contracted position at the bottom without moving your limbs for a set number of seconds', 'Cable machine', 'wger', 'CC-BY-SA 4', 'HexoctusEngineering', 'https://wger.de/en/exercise/2540/view/'),
  ('45e44940-d4a0-4c66-8cbb-7afe785d5610', 'Lateral Push Off', 'Calves', 'Push off the ground and land on one leg and regain balance before jumping to the other leg', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'cleen', 'https://wger.de/en/exercise/1325/view/'),
  ('2d580008-4918-430a-b0bd-4fcfe8783195', 'Lateral Raise Isometric', 'Shoulders', 'An isometric lateral raise is a shoulder exercise where you hold your arms out to the sides at waist height for a set amount of time instead of moving up and down', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'HexoctusEngineering', 'https://wger.de/en/exercise/2538/view/'),
  ('63375f5b-2d81-471c-bea4-fc3d207e96cb', 'Lateral Raises', 'Shoulders', 'This exercise works the deltoid muscle of the shoulder. The movement starts with the arms straight, and the hands holding weights at the sides or in front of the body. Body is in a slight forward-leaning position with hips and knees bent a little. Arms are kept straight or slightly bent, and raised through an arc of movement in the coronal plane that terminates when the hands are at approximately shoulder height. Weights are lowered to the starting position, completing one rep. When using a cable machine the individual stands with the coronal plane in line with the pulley, which is at or near the ground.[9] The exercise can be completed one shoulder at a time (with the other hand used to stabilize the body against the weight moved), or with both hands simultaneously if two parallel pulleys are available.', 'Dumbbell', 'wger', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/348/view/'),
  ('57263316-6f34-4539-952b-b07e09bac3ba', 'Lateral Rows on Cable, One Armed', 'Shoulders', 'Set cable at waist height, start with arm across your belly and move han over and out too other side, one arm at the time.', 'Cable machine', 'wger', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/349/view/'),
  ('c5015ed9-042b-42d3-9dac-13759ea9571e', 'Lateral Walk', 'Glutes', 'Lateral walks, also known as side steps or squat walks, are a type of exercise where you move sideways in a squatting position. They can be performed with or without resistance bands. These exercises strengthen the hip abductors, glutes, and other stabilizing muscles.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'cozyGalvinism', 'https://wger.de/en/exercise/1514/view/'),
  ('dac3c714-f0c6-4d97-8283-17be7dd77b65', 'Lateral-to-Front Raises', 'Shoulders, Trapezius', '-(1) Perform a lateral raise, pausing at the top of the lift (2).
-Instead of lowering the weight, bring it to the front of your body so that you appear to be at the top position of a front raise.  You will do this by using a Pec Fly motion, maintaining straight arms. (3)
-Now lower the weight to your quadriceps, or, in other words, lower the dumbbells as though you are completing a Front Raise repetition. (4)
-Reverse the motion:  Perform a front raise (5), at the apex of the lift use a Reverse Fly motion to position the weights at the top of a Lateral Raise (6), and finally, lower the weights until your palms are essentially touching the sides of your thighs (7).  THIS IS ONE REP.
(1) l  front view(2) -l-  FV  (3) l-  side view   (4) l  SV/FV   (5) l-  SV (6) -l-  FV  (7)  l  FV/SV', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'nate303303', 'https://wger.de/en/exercise/351/view/'),
  ('28d18142-8777-4dba-a3a1-6151cec94500', 'Lean-Away Cable Lateral Raise', 'Shoulders', 'Set a cable pulley at the lowest position and attach a single handle. Stand side-on to the machine, hold the frame with your near hand and lean your body away so you hang at an angle. With the far hand, grasp the handle in front of your hips and raise your arm out to the side to shoulder height with a slight bend in the elbow. Lower slowly. The lean increases tension on the side delts at the bottom of the movement. Complete all reps, then switch sides.', 'Cable machine', 'wger', 'CC-BY-SA 4', 'trs1800', 'https://wger.de/en/exercise/2624/view/'),
  ('7f8997d2-e21f-492f-a470-b9f0c5e54f1d', 'Left levator scapulae stretch', null, 'Starting position:
Start standing up or sitting down. Turn your head to the left, around 45 degrees or just above your nipple. Place your right hand behind your back or sit on it. Take your left hand and use it to hold the back of your head. Lean your head down slightly.
Steps:
- After assuming the starting position, press your head against your left hand with slight force. Your hand should press back with equal force, so that your head doesn''t move. Hold this position.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/1013/view/'),
  ('2ecf2e55-c1f3-40ac-b20e-0954f41a2021', 'Left neck stretch', null, 'Starting position:
Sit or stand with your back straight.
Steps:
- Tilt your head to the side.
- Take the hand closer to your head and use it to grab your head from the other side.
- Push with your hand against your head and with your head against your hand so that the forces balance out and your head stays still.
- Maintain this tension until the end of the exercise.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/1008/view/'),
  ('505d6a28-1e24-4349-ab2b-49af3300e08e', 'Leg and hip stretch', 'Hamstrings, Glutes, Quads', 'Gentle movements to improve the flexibility of the lower body and release tension in the hips.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'MrAlfaRobot', 'https://wger.de/en/exercise/1589/view/'),
  ('48836f44-efcd-4471-a456-5f024936025a', 'Leg Curl', 'Hamstrings, Glutes', 'The leg curl, also known as the hamstring curl, is an isolation exercise that targets the hamstring muscles. The exercise involves flexing the lower leg against resistance towards the buttocks. Other exercises that can be used to strengthen the hamstrings are the glute-ham raise and the deadlift.', null, 'wger', 'CC0', 'BFad07', 'https://wger.de/en/exercise/364/view/'),
  ('ca514fad-c6ce-47b0-93a0-dc73a3507099', 'Leg curl with elastic', 'Calves', 'Standing position: Place the band under your feet in the middle of your foot and grasp it with a hammer grip.', 'Resistance band', 'wger', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/1603/view/'),
  ('3bc8b411-a28d-4e1c-a6d1-769e18fe9881', 'Leg Curls (laying)', 'Hamstrings', 'Lay on a bench and put your calves behind the leg holder (better if they are hold on around the lower calves). Hold a grip on the bars to make sure the body is firmly in place. Bend your legs bringing the weight up, go slowly back. During the exercise the body should not move, all work is done by the legs.', null, 'wger', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/365/view/'),
  ('440a5184-de58-4a86-a7ba-76ddeafaa855', 'Leg Curls (sitting)', 'Hamstrings', null, null, 'wger', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/366/view/'),
  ('74a817dd-d3b8-4680-afad-aad1ec2cf8bc', 'Leg Curls (sitting) (Custom)', 'Hamstrings', 'Perform Leg Curls (sitting) with controlled form, keeping tension on the target muscles, pausing briefly at the peak contraction, then returning slowly under control without using momentum.', null, 'wger', 'CC-BY-SA 4', 'ruochenma', 'https://wger.de/en/exercise/2708/view/'),
  ('49189e88-40b6-4c0d-a784-0cc3abbb8e75', 'Leg Curls (standing)', 'Hamstrings', null, null, 'wger', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/367/view/'),
  ('62170477-90ec-463c-907e-9e523abc0a15', 'Leg Extension', 'Quads', 'The leg extension is a resistance weight training exercise that targets the quadriceps muscle in the legs. The exercise is done using a machine called the Leg Extension Machine. There are various manufacturers of these machines and each one is slightly different. Most gym and weight rooms will have the machine in their facility. The leg extension is an isolated exercise targeting one specific muscle group, the quadriceps. It should not be considered as a total leg workout, such as the squat or deadlift. The exercise consists of bending the leg at the knee and extending the legs, then lowering them back to the original position.', null, 'wger', 'CC0', 'BFad07', 'https://wger.de/en/exercise/369/view/'),
  ('16026ebc-f2d6-4b65-ac21-0463acc49c7f', 'Leg Extension (Custom)', 'Quads', 'Perform Leg Extension with controlled form, keeping tension on the target muscles, pausing briefly at the peak contraction, then returning slowly under control without using momentum.', null, 'wger', 'CC-BY-SA 4', 'ruochenma', 'https://wger.de/en/exercise/2709/view/'),
  ('88c4d3e5-3837-4c71-bb06-c45e147496cc', 'Leg Extension Isometric', 'Quads', 'An isometric leg extension is a strengthening exercise where you contract your quadriceps muscles against an immovable resistance without changing the length of the muscle or moving your knee joint.', null, 'wger', 'CC-BY-SA 4', 'HexoctusEngineering', 'https://wger.de/en/exercise/2535/view/'),
  ('66a42396-c207-44da-bc75-758a89d32404', 'Leg Press', 'Hamstrings, Calves, Glutes, Quads', 'The leg press is a weight training exercise in which the individual pushes a weight or resistance away from them using their legs.', null, 'wger', 'CC0', 'BFad07', 'https://wger.de/en/exercise/371/view/'),
  ('7bc33f4f-3967-4f24-b810-08fcbc568976', 'Leg Press (Custom)', 'Quads', 'Perform the leg press with controlled form, feet shoulder-width on the platform, lower slowly without letting the pelvis lift, keep knees tracking over toes, breathe steadily.', null, 'wger', 'CC-BY-SA 4', 'ruochenma', 'https://wger.de/en/exercise/2749/view/')
on conflict do nothing;

